  FT["PH-H6806"] = {"id":"PH-H6806","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8331_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Bambang市","en":"An Act Establishing A Na Tional High School in the Municipality of Bambang, Province of Nueva Vizcaya, To Be Known As the Bambang National High School, and Appropriating Funds Therefor","orig":"An Act Establishing A Na Tional High School in the Municipality of Bambang, Province of Nueva Vizcaya, To Be Known As the Bambang National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8331","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-06-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8331_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6806-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports, a national high school in the Municipality of Bambang, Province of Nueva Vizcaya, to be known as the Bambang National High School."}},{"id":"PH-H6806-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6806-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97"};
  FT["PH-H6807"] = {"id":"PH-H6807","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8332_1997.html","fetchedAt":"2026-10-06","articleCount":21,"structureMode":"ARTICLE","title":{"zh":"对第 7908 号共和国法的修改","en":"An Act Amending Republic Act No. 7908, Entitled, \"An Act Granting the Multi-media Telephony, Incorporated, A Franchise To Construct, Establish, Operate and Maintain Radio Paging System in the Philippines, and For Other Purposes\"","orig":"An Act Amending Republic Act No. 7908, Entitled, \"An Act Granting the Multi-media Telephony, Incorporated, A Franchise To Construct, Establish, Operate and Maintain Radio Paging System in the Philippines, and For Other Purposes\""},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 8332","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-06-30","completenessNote":"全文，共 21 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8332_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6807-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Act No. 7908 is hereby amended to read as follows:\n\""}},{"id":"PH-H6807-A1-d2","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Multi-Media Telephony, Inc., hereunder referred to as the grantee, its successors or assigns, a franchise to construct, establish, install, maintain and operate for commercial purposes and in the public interest, the business of providing telecommunications services throughout the Philippines and between the Philippines and other countries and territories, including mobile, cellular, wired or wireless telecommunications systems and their value-added services such as, but not limited to, transmission of voice, data, facsimile, control signs, audio and video, information and service bureau, and all other telecommunications systems technologies as are at present available or will be made available through technological advances or innovations in the future, and construct, acquire, lease and operate or manage transmitting and receiving stations, lines, cables or systems, as is, or are, convenient or essential to efficiently carry out the purposes of this franchise.\n\""},"dupIndex":2},{"id":"PH-H6807-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof.\n\""}},{"id":"PH-H6807-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission, hereinafter referred to as the Commission, a certificate of public convenience or the appropriate permits and licenses for the location, construction, installation and operation of its telecommunications systems. In issuing the certificate, the Commission shall have the power to impose such conditions relative to the construction, operation, maintenance, or service level of the telecommunications system. The Commission shall have the authority to regulate the construction and operation of its telecommunications systems. The grantee shall not use any frequency in the radio spectrum without having been authorized by the Commission. Such certificate shall state the areas covered and date the grantee shall commence the service. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority, permits or licenses.\n\""}},{"id":"PH-H6807-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall conform to the ethics of honest enterprise and shall not use its stations for obscene or indecent transmission or for dissemination of deliberately false information or willful misrepresentation, or assist in subversive or treasonable acts.\n\"The grantee shall provide basic or enhanced telephone service in any municipality in the Philippines where it has an approved certificate of public convenience for the establishment, operation and maintenance of a local exchange service, without discrimination to any applicant therefor, in the order of the date of their applications, up to the limit of the capacity of its local telephone exchange, and should the demand for the telephone service at any time increase beyond the capacity thereof, the grantee shall increase the same to meet such demand: Provided, That in case the total demand to be satisfied by the expansion is less than the smallest viable local exchange available in the market as determined by the Commission, the grantee shall not be obliged to furnish said service, unless the applicant for telephone service defrays the actual expenses for the installation of the telecommunication apparatus necessary for such services and in such case the Commission may extend the time within which the grantee shall furnish such service.\n\"The grantee shall operate and maintain all its stations, lines, cables, systems and equipment for the transmission and reception of messages, signals and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve or change such stations, lines, cables, systems and equipment to keep abreast with the advances in science and technology.\n\""}},{"id":"PH-H6807-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Rates for Services. – The charges and rates for telecommunications services of the grantee, except the rates and charges on those that may hereafter be declared or considered as non-regulated services, whether flat rates or measured rates or variation thereof, shall be subject to the approval of the Commission or its legal successors. The rates to be charged by the grantee shall be unbundled, separable and distinct among the services offered and shall be determined in such a manner that regulated services do not subsidize the unregulated ones.\n\""}},{"id":"PH-H6807-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations, transmitters, facilities or equipment of the grantee, to temporarily suspend the operation of any station, transmitter, facility or equipment in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations, transmitters, facilities or equipment during the period when the franchise shall be so operated.\n\"The radio spectrum is a finite resource that is part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn anytime, after due process.\n\""}},{"id":"PH-H6807-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked, in the event the grantee fails to comply with any of the following conditions:\n\"(a) Commence operations within three (3) years from the approval of its permit by the National Telecommunications Commission;\n\"(b) Operate continuously for two (2) years; and \"(c) Commence operatmence operations within three (3) years from the approval of its permit by the National Telecommunications Commission;\n\"(b) Operate continuously for two (2) years; and \"(c) Commence operations within five (5) years from the effectivity of this Act.\n\""}},{"id":"PH-H6807-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Non-acceptance shall render the franchise void.\n\""}},{"id":"PH-H6807-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Bond. – The grantee shall file a bond issued in favor of the National Telecommunications Commission, which shall determine the amount, to guarantee the compliance with and fulfillment of the conditions under which this franchise is granted. If after five (5) years from the date of the approval of its permit by the Commission, the grantee shall have fulfilled the same, the bond shall be cancelled by the Commission. Otherwise, the bond shall be forfeited in favor of the government and the franchise ipso facto revoked.\n\""}},{"id":"PH-H6807-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Right of Interconnection. – The grantee is hereby authorized to connect or demand connection of its telecommunications systems to any other telecommunications systems installed, operated and maintained by any other duly authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public under such terms and conditions mutually agreed upon by the parties concerned and the same shall be subject to the review or modification of the Commission.\n\""}},{"id":"PH-H6807-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay the value-added tax under Republic Act No. 7716 or a franchise tax of three percent (3%) per annum or at such percentage as may be prescribed by law, on all gross receipts of its telecommunications business transacted under this franchise, whichever is higher: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\n\"The grantee shall file the return with and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue.\n\""}},{"id":"PH-H6807-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Gross Receipts. – The grantee, its successors or assigns, shall keep a separate account of the gross receipts of the business transacted by it and shall furnish the Commission on Audit and the National Treasury a copy of such account not later than the thirty-first day of January of each year, for the preceding twelve (12) months.\n\""}},{"id":"PH-H6807-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Books and Accounts. – The books and accounts of the grantee, its successors or assigns, shall always be open to the inspection of the Commissioner on Audit or his duly authorized representatives, and it shall be the duty of the grantee to submit to the Commission on Audit, two (2) copies of the quarterly reports on the gross receipts, the net profits and the general condition of the business.\n\""}},{"id":"PH-H6807-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, transmitters, facilities and equipment of the grantee.\n\""}},{"id":"PH-H6807-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any corporation or entity, nor shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions, and limitations of this Act.\n\""}},{"id":"PH-H6807-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Dispersal of Ownership. – In accordance with the constitutional provisions to encourage public participation in the public utilities, the grantee shall offer at least thirty per centum (30%) of its outstanding capital stock or a higher percentage that may hereafter be provided by law in any securities exchange in the Philippines within five (5) years from the commencement of its operations. Noncompliance therewith shall render the franchise ipso facto revoked.\n\""}},{"id":"PH-H6807-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid.\n\""}},{"id":"PH-H6807-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Repealability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for.\n\""}},{"id":"PH-H6807-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of its franchise and on its operations within sixty (60) days from the end of every year.\n\""}},{"id":"PH-H6807-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general publication.\""}}],"pack":"ph-p97"};
  FT["PH-H6808"] = {"id":"PH-H6808","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8333_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Alicia市","en":"An Act Establishing A Vocational High School in the Municipality of Alicia, Province of Isabela, To Be Known As the Alicia Vocational School, and Appropriating Funds Therefor","orig":"An Act Establishing A Vocational High School in the Municipality of Alicia, Province of Isabela, To Be Known As the Alicia Vocational School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8333","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-07-05","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8333_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6808-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports, a vocational high school in the Municipality of Alicia, Province of Isabela, to be known as the Alicia Vocational School."}},{"id":"PH-H6808-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6808-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the annual General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6808-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97"};
  FT["PH-H6809"] = {"id":"PH-H6809","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8334_1997.html","fetchedAt":"2026-10-06","articleCount":21,"structureMode":"ARTICLE","title":{"zh":"授予 Eastern Visayas 电话公司在莱特等五省及所有组成市建设、运营和维护本地交换网络的特许经营权法案","en":"An Act Granting the Eastern Visayas Telephone Company, Inc., A Franchise To Construct, Establish, Install, Maintain and Operate Local Exchange Network in the Provinces of Leyte, Southern Leyte, Northern Samar, Western Samar, and Eastern Samar, Including All Component Or Chartered Cities Therein","orig":"An Act Granting the Eastern Visayas Telephone Company, Inc., A Franchise To Construct, Establish, Install, Maintain and Operate Local Exchange Network in the Provinces of Leyte, Southern Leyte, Northern Samar, Western Samar, and Eastern Samar, Including All Component Or Chartered Cities Therein"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8334","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-07-10","completenessNote":"全文，共 21 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8334_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6809-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Eastern Visayas Telephone Company, Inc., hereunder referred to as the grantee, its successors or assigns, a franchise to construct, establish, install, maintain and operate for commercial purposes and in the public interest, local exchange network, including public calling stations or pay telephone stations or wireless local loop and for such purpose provide basic telephone service or other means related to the foregoing now known to science or which in the future may be developed, in the provinces of Leyte, Southern Leyte, Northern Samar, Western Samar, and Eastern Samar, including all component or chartered cities therein, for public domestic telecommunications."}},{"id":"PH-H6809-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof. In no way shall the operations of the grantee, nor the radiated power of its stations or facilities, exceed that required to cover the area where it is allowed to operate."}},{"id":"PH-H6809-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission, hereinafter referred to as the Commission, a certificate of public convenience or the appropriate permits and licenses for the location, construction, installation and operation of its telecommunications systems. In issuing the certificate, the Commission shall have the power to impose such conditions relative to the construction, operation, maintenance, or service level of the telecommunications system. The Commission shall have the authority to regulate the construction and operation of its telecommunications systems. The grantee shall not use any frequency in the radio spectrum without having been authorized by the Commission. Such certificate shall state the areas covered and date the grantee shall commence the service. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority, permits or licenses."}},{"id":"PH-H6809-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall conform to the ethics of honest enterprise and shall not use its stations for obscene or indecent transmission or for dissemination of deliberately false information or willful misrepresentation, or assist in subversive or treasonable acts.\nThe grantee shall provide basic or enhanced telephone service in any municipality in the Philippines where it has an approved certificate of public convenience for the establishment, operation, and maintenance of a local exchange service, without discrimination to any applicant therefor, in the order of the date of their applications, up to the limit of the capacity of its local telephone exchange, and should the demand for the telephone service at any time increase beyond the capacity thereof, the grantee shall increase the same to meet such demand: Provided, That in case the total demand to be satisfied by the expansion is less than the smallest viable local exchange available in the market as determined by the Commission, the grantee shall not be obliged to furnish said service, unless the applicant for telephone service defrays the actual expenses for the installation of the telecommunication apparatus necessary for such services and in such case the Commission may extend the time within which the grantee shall furnish such service.\nThe grantee shall operate and maintain all its stations, lines, cables, systems and equipment for the transmission and reception of messages, signals and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve or change such stations, lines, cables, systems and equipment to keep abreast with the advances in science and technology."}},{"id":"PH-H6809-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Rates for Services. – The charges and rates for telecommunications services of the grantee, except the rates and charges on those that may hereafter be declared or considered as Non-regulated services, whether flat rates or measured rates or variation thereof, shall be subject to the approval of the Commission or its legal successors. The rates to be charged by the grantee shall be unbundled, separable and distinct among the services offered and shall be determined in such a manner that regulated services do not subsidize the unregulated ones."}},{"id":"PH-H6809-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations, transmitters, facilities or equipment of the grantee, to temporarily suspend the operation of any station, transmitter, facility or equipment in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee for the use of said stations, transmitters, facilities or equipment during the period when they shall be so operated.\nThe radio spectrum is a finite resource that is a part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the state and may be withdrawn anytime, after due process."}},{"id":"PH-H6809-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked, in the event the grantee fails to comply with any of the following conditions:\na. Commence operations within three (3) years from the approval of its operating permit or provisional authority by the National Telecommunications Commission;\nb. Operate continuously for two (2) years; and\nc. Commence operations within five (5) years from the effectivity of this Act."}},{"id":"PH-H6809-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Non-acceptance shall render the franchise void."}},{"id":"PH-H6809-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Bond. – If the grantee is not yet operational, the grantee shall file a bond issued in favor of the National Telecommunications Commission, which shall determine the amount, to guarantee the compliance with and fulfillment of the conditions under which this franchise is granted. If after five (5) years from the date of the approval of its permit by the Commission, the grantee shall have fulfilled the same, the bond shall be cancelled by the Commission. Otherwise the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H6809-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Right of Interconnection. – The grantee is hereby authorized to connect or demand connection of its telecommunications systems to any other telecommunications systems installed, operated and maintained by any other duly-authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public under such terms and conditions mutually agreed upon by the parties concerned and the same shall be subject to the review or modification of the Commission."}},{"id":"PH-H6809-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay the value-added tax under Republic Act No. 7716 or a franchise tax of three percent (3%) per annum or at such percentage as may be prescribed by law, on all gross receipts of its telecommunications business transacted under this franchise, whichever is higher: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with, and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6809-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Gross Receipts. – The grantee, its successors or assigns, shall keep a separate account of the gross receipts of the business transacted by it and shall furnish the Commission on Audit and the National Treasury a copy of such account not later than the 31st day of January of each year, for the preceding twelve (12) months."}},{"id":"PH-H6809-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Books and Accounts. – The books and accounts of the grantee, its successors or assigns, shall always be open to the inspection of the Commissioner on Audit or his authorized representatives, and it shall be the duty of the grantee to submit to the Commission on Audit, two (2) copies of the quarterly reports on the gross receipts, the net profits and the general condition of the business."}},{"id":"PH-H6809-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, transmitters, facilities and equipment of the grantee."}},{"id":"PH-H6809-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any corporation or entity, nor shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines, except when such person, firm, company, corporation or entity has a valid and existing legislative franchise for telecommunications or it is in pursuance of the provisions of Section 16 of this Act. Any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H6809-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Dispersal of Ownership. – In accordance with the constitutional provisions to encourage public participation in the public utilities, the grantee shall offer at least thirty per centum (30%) of its outstanding capital stock or a higher percentage that may hereafter be provided by law in any securities exchange in the Philippines within ten (10) years from the commencement of its operations or from the effectivity of this Act, whichever is later. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H6809-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6809-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Repealability and Non-exclusivity Clause. – This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6809-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of its franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6809-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general publication."}},{"id":"PH-H6809-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Eastern Visayas Telephone Company, Inc., A Franchise To Construct, Establish, Install, Maintain and Operate Local Exchange Network in the Provinces of Leyte, Southern Leyte, Northern Samar, Western Samar, and Eastern Samar, Including All Component Or Chartered Cities Therein","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6810"] = {"id":"PH-H6810","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8335_1997.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"修订 Calbayog 市宪章的法案","en":"An Act To Revise the Charter of the City of Calbayog","orig":"An Act Amending Section Eleven of Republic Act Numbered Three Thousand Two Hundred Seventy-nine, Otherwise Known As \"An Act To Revise the Charter of the City of Calbayog\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8335","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-07-11","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8335_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 11 条，缺 5、6、7、8、9、10）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6810-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 11 of Republic Act No. 3279, entitled: \"An Act to Revise the Charter of the City of Calbayog,\" is hereby amended to read as follows:\n\""}},{"id":"PH-H6810-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Constitution and Organization of the Sangguniang Panlungsod; Compensation of Members Thereof. – The sangguniang panlungsod shall be the legislative body of the city, and shall be composed of the vice-mayor, who shall be its presiding officer and shall be elected at large by the qualified voters of the City, and twelve (12) sangguniang panlungsod members who shall be elected by districtt by the qualified voters therein to be apportioned as follows: six (6) for Oquendo and Tinambacan district and six (6) for Calbayog district.\n\"The Oquendo and Tinambacan district will be comprised of the following barangays: Manuel Barral, Sr., Bayo, Cabatuan, Cabugawan, Cag-anibong, Cagbilwang, Catabunan, Dawo, Dinagan, Longsob, Mabini II, Macatingog, Mantaong, Mawacat, Oquendo Proper, Panlayahan, Pilar, Rizal II, Roxas II, Sigo, Baja, Begaho, Cabacungan, Cabicahan, Capacuhan, Cag-anahaw, Cagbayang, Caybago, De Victoria, Dinabongan, Hibabngan, Hogon Rosales, Jose Roño, Lapaan, Libertad, Mag-ubay, Nabang, Oboob, Panoypoy, Quezon, San Rufino, San Isidro, Sinidman Occidental, Sinidman Oriental, Talahiban, Tarabucan, Amampacang, Ba-ay, Bante, Banti-an, Binaliw, Bugtong, Caglanipao Sur, Cagmanipes Sur, Cagmanipes Norte, Cagnipa, Cag-olango, Cangomaud, Danao I, Danao II, Malaga, Malajog, Malayog, Malopalo, Manguino-o, Marca Tubig, Peña, Salhag, San Joaquin, Tinambacan Sur, Tinambacan Norte, Tinaplacan, and Tomaligues.\n\"Calbayog district will be comprised of the following barangays: East Awang, West Awang, Bagacay, Cagbanayacao, Cagboborac, Calocnayan, Carayman, Cogon, Guinbaoyan Norte, Guinbaoyan Sur, Higasaan, Mabini I, Naga, Olera, Pinamorotan, Rawis, Rizal I, Salvacion, San Antonio, Tapae, Aguit-itan, Alibaba, Balud, Central, Esperanza, Geragaan, Guin-on, Hamorawon, Himalandrog, Langoyon, La Paz, Migara, Nijaga, Osmeña, San Jose, Sinantan, Tabawan, Tanval, Victory, Villahermosa, Acedillo, Anislag, Bagong Lipunan, Basud, Bontay, Cacaransan, Cagsalaosao, Capoocan, Carmen, Dagum, Helino, Lonoy, Navarro, Obrero, Pagbalican, Palanas, Cara, Panonongon, Patong, Payahan, San Policarpio, Saputan, Trinidad, Buenavista, Cahumpan, Canjumadac, Dinawacan, Gabay, Gadgaran, Gasdo, Hibatang, Jacinto, Jimautan, Kalilihan, Kilikili, Limarayon, Looc, Mancol, Matobato, Maybog, Maysalong, Nag-uma, Palanogan, Roxas I, and Tigbe.\""}},{"id":"PH-H6810-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon approval of this Act, the President of the Philippines shall, upon the recommendation of the Secretary of the Department of the Interior and Local Government, appoint the additional members of the sangguniang panlungsod to serve until their successors shall have been elected and qualified."}},{"id":"PH-H6810-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All laws, decrees, executive orders, rules and regulations inconsistent herewith are hereby repealed or modified accordingly."}},{"id":"PH-H6810-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon publication in at least two (2) newspapers of national circulation.\nApproved, July 11, 1997."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act To Revise the Charter of the City of Calbayog","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6811"] = {"id":"PH-H6811","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8336_1997.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"授予 Real Time 通信公司在南他加禄大区全境建设、安装、设立、运营和维护广播与电视站的特许经营权法案","en":"An Act Granting Real Time Communications, Inc., A Franchise To Construct, Install, Establish, Operate and Maintain Radio/Television Stations Throughout the Southern Tagalog Region","orig":"An Act Granting Real Time Communications, Inc., A Franchise To Construct, Install, Establish, Operate and Maintain Radio/Television Stations Throughout the Southern Tagalog Region"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8336","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-07-14","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8336_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6811-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Real Time Communications, Inc., hereunder referred to as the grantee, its successors or assigns, a franchise to construct, install, establish, operate and maintain for commercial purposes and in the public interest, radio and/or television broadcasting stations throughout the Southern Tagalog Region, where frequencies and/or channels are still available for radio and/or television broadcasting, with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations."}},{"id":"PH-H6811-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6811-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for the construction and operation of its stations and facilities and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6811-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations or facilities, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations or facilities for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, to the detriment of the public interest, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H6811-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations or facilities of the grantee, to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when they shall be so operated.\nThe radio spectrum is a finite resource that is a part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn anytime, after due process."}},{"id":"PH-H6811-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to comply with any of the following conditions:\na. Commence operations within one (1) year from the approval of its permit by the National Telecommunications Commission;\nb. Operate continuously for two (2) years; and\nc. Commence operations within three (3) years from the effectivity of this Act."}},{"id":"PH-H6811-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Non-acceptance shall render the franchise void."}},{"id":"PH-H6811-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Bond. – The grantee shall file a bond issued in favor of the National Telecommunications Commission, which shall determine the amount, to guarantee the compliance with and fulfillment of the conditions under which this franchise is granted. If after three (3) years from the date of the approval of its permit by the Commission, the grantee shall have fulfilled the same, the bond shall be cancelled by the Commission. Otherwise, the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H6811-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay the value-added tax under Republic Act No. 7716 or a franchise tax of five percent (5%) per annum or at such percentage as may be prescribed by law, on all gross receipts of its telecommunications business transacted under this franchise, whichever is higher: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with, and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6811-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Self-Regulation by and Undertaking of Grantee. – The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast from its stations: Provided, That the grantee, during any broadcast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/ or incite treason, rebellion, or sedition; or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6811-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6811-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6811-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Dispersal of Ownership. – In accordance with constitutional provisions to encourage public participation in public utilities, the grantee shall offer at least thirty per centum (30%) of its outstanding capital stock or a higher percentage that may hereafter be provided by law in any securities exchange in the Philippines within five (5) years from the time it has achieved the status of a National Broadcasting Network. A National Broadcasting Network is hereby defined as one that operates three or more radio and/or television stations. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H6811-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy Law. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law which Congress may hereafter enact."}},{"id":"PH-H6811-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6811-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Repealability and Non-exclusivity Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6811-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6811-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general publication in the Philippines."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Real Time Communications, Inc., A Franchise To Construct, Install, Establish, Operate and Maintain Radio/Television Stations Throughout the Southern Tagalog Region","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6812"] = {"id":"PH-H6812","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8337_1997.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"授予 Meridian Telekoms，Inc. 在菲律宾全境建设、安装、设立、维护、租赁和运营有线及无线电信系统的特许经营权法案","en":"An Act Granting the Meridian Telekoms, Inc., A Franchise To Construct, Install, Establish, Maintain, Lease and Operate Wire And/Or Wireless Telecommunications Systems Throughout the Philippines","orig":"An Act Granting the Meridian Telekoms, Inc., A Franchise To Construct, Install, Establish, Maintain, Lease and Operate Wire And/Or Wireless Telecommunications Systems Throughout the Philippines"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 8337","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-07-14","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8337_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6812-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Meridian Telekoms, Inc., hereunder referred to as the grantee, its successors or assigns, a franchise to construct, establish, install, maintain and operate for commercial purposes and in the public interest, the business of providing telecommunications services throughout the Philippines and between the Philippines and other countries and territories, including mobile, cellular, wired or wireless telecommunications systems and their value-added services such as, but not limited to, transmission of voice, data, facsimile, control signs, audio and video, information and service bureau, and all other telecommunications systems technologies as are at present available or will be made available through technological advances or innovations in the future, and construct, acquire, lease and operate or manage transmitting and receiving stations, lines, cables or systems, as is, or are, convenient or essential to efficiently carry out the purpose of this franchise."}},{"id":"PH-H6812-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6812-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission, hereinafter referred to as the Commission, a certificate of public convenience or the appropriate permits and licenses for the location, construction, installation and operation of its telecommunications systems. In issuing the certificate, the Commission shall have the power to impose such conditions relative to the construction, operation, maintenance, or service level of the telecommunications system. The Commission shall have the authority to regulate the construction and operation of its telecommunications systems. The grantee shall not use any frequency in the radio spectrum without having been authorized by the Commission. Such certificate shall state the areas covered and date the grantee shall commence the service. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority, permits or licenses."}},{"id":"PH-H6812-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall conform to the ethics of honest enterprise and shall not use its stations for obscene or indecent transmission or for dissemination of deliberately false information or willful misrepresentation, or assist in subversive or treasonable acts. The grantee shall provide basic or enhanced telephone service in any municipality in the Philippines where it has an approved certificate of public convenience for the establishment, operation, and maintenance of a local exchange service, without discrimination to any applicant therefore, in the order of the date of their applications, up to the limit of the capacity of its local telephone exchange, and should the demand for the telephone service at any time increase beyond the capacity thereof, the grantee shall increase the same to meet such demand: Provided, That in case the total demand to be satisfied by the expansion is less than the smallest viable local exchange available in the market as determined by the Commission, the grantee shall not be obliged to furnish said service, unless the applicant for telephone service defrays the actual expenses for the installation of the telecommunication apparatus necessary for such services and in such case the Commission may extend the time within which the grantee shall furnish such service.\nThe grantee shall operate and maintain all its stations, lines, cables, systems and equipment for the transmission and reception of messages, signals and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve or change such stations, lines, cables, systems and equipment to keep abreast with the advances in science and technology."}},{"id":"PH-H6812-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Rates for Services. – The charges and rates for telecommunications services of the grantee, except the rates and charges on those that may hereafter be declared or considered as non-regulated services, whether flat rates or measured rates or variation thereof, shall be subject to the approval of the Commission or its legal successors. The rates to be charged by the grantee shall be unbundled, separable and distinct among the services offered and shall be determined in such a manner that regulated services do not subsidize the unregulated ones."}},{"id":"PH-H6812-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations, transmitters, facilities or equipment of the grantee, to temporarily suspend the operation of any station, transmitter, facility or equipment in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee for the use of said stations, transmitters, facilities or equipment during the period when they shall be so operated.\nThe radio spectrum is a finite resource that is a part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the state and may be withdrawn anytime, after due process."}},{"id":"PH-H6812-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked, in the event the grantee fails to comply with any of the following conditions:\na. Commence operations within three (3) years from the approval of its permit by the National Telecommunications Commission;\nb. Operate continuously for two (2) years; and\nc. Commence operations within five (5) years from the effectivity of this Act."}},{"id":"PH-H6812-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Non-acceptance shall render the franchise void."}},{"id":"PH-H6812-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Bond. – The grantee shall file a bond issued in favor of the National Telecommunications Commission, which shall determine the amount, to guarantee the compliance with the fulfillment of the conditions under which this franchise is granted. If after five (5) years from the date of the approval of its permit by the Commission, the grantee shall have fulfilled the same, the bond shall be cancelled by the Commission. Otherwise the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H6812-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Right of Interconnection. – The grantee is hereby authorized to connect or demand connection of its telecommunications systems to any other telecommunications systems installed, operated and maintained by any other duly-authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public under such terms and conditions mutually agreed upon by the parties concerned and the same shall be subject to the review or modification of the Commission."}},{"id":"PH-H6812-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay the value-added tax under Republic Act No. 7716 or a franchise tax of three percent (3%) per annum or at such percentage as may be prescribed by law, on all gross receipts of its telecommunications business transacted under this franchise, whichever is higher: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with, and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6812-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Gross Receipts. – The grantee, its successors or assigns, shall keep a separate account of the gross receipts of the business transacted by it and shall furnish the Commission on Audit and the National Treasury a copy of such account not later than the thirty-first day of January of each year, for the preceding twelve (12) months."}},{"id":"PH-H6812-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Books and Accounts. – The books and accounts of the grantee, its successors or assigns, shall always be open to the inspection of the Commissioner on Audit or his authorized representatives, and it shall be the duty of the grantee to submit to the Commission on Audit, two (2) copies of the quarterly reports on the gross receipts, the net profits and the general condition of the business."}},{"id":"PH-H6812-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, transmitters, facilities and equipment of the grantee."}},{"id":"PH-H6812-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any corporation or entity, nor shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H6812-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Dispersal of Ownership. – In accordance with the constitutional provisions to encourage public participation in the public utilities, the grantee shall offer at least thirty per centum (30%) of its outstanding capital stock or a higher percentage that may hereafter be provided by law in any securities exchange in the Philippines within five (5) years from the commencement of its operations. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H6812-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6812-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Repealability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6812-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of its franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6812-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general publication."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Meridian Telekoms, Inc., A Franchise To Construct, Install, Establish, Maintain, Lease and Operate Wire And/Or Wireless Telecommunications Systems Throughout the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6813"] = {"id":"PH-H6813","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8338_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将伊莎贝拉省圣地亚哥市南伊莎贝拉区医院升格为三级综合医院，名称为南伊莎贝拉总医院，并为此拨款的法案","en":"An Act Upgrading the Southern Isabela District Hospital in Santiago City, Province of Isabela, Into A Tertiary General Hospital, To Be Known As the Southern Isabela General Hospital, and Appropriating Funds Therefor","orig":"An Act Upgrading the Southern Isabela District Hospital in Santiago City, Province of Isabela, Into A Tertiary General Hospital, To Be Known As the Southern Isabela General Hospital, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 8338","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-08-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8338_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6813-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Southern Isabela District Hospital in Santiago City, Province of Isabela, is hereby upgraded into a tertiary general hospital under the direct technical and administrative supervision of the Department of Health, to be known as the Southern Isabela General Hospital."}},{"id":"PH-H6813-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Health shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6813-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6813-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Upgrading the Southern Isabela District Hospital in Santiago City, Province of Isabela, Into A Tertiary General Hospital, To Be Known As the Southern Isabela General Hospital, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6814"] = {"id":"PH-H6814","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8339_1997.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"授予 Air Philippines Corporation 设立、运营和维护国内与国际航空运输服务的特许经营权法案","en":"An Act Granting Air Philippines Corporation (Air Philippines), A Franchise To Establish, Operate and Maintain Domestic and International Air Transport Services","orig":"An Act Granting Air Philippines Corporation (Air Philippines), A Franchise To Establish, Operate and Maintain Domestic and International Air Transport Services"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8339","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-08-08","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8339_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6814-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Air Philippines Corporation, hereunder referred to as the grantee, its successors or assigns, a franchise to establish, operate and maintain transport services for the carriage of passengers, mail, goods and property by air, domestic and international.\nAir transport services shall include the maintenance and operation of hangars and aircraft service stations and facilities and other services of similar nature which may be necessary, convenient or useful as an auxiliary to aircraft transportation.\nThe grantee shall have the right at its terminal and landing fields, as well as in its aircraft, to construct, operate and maintain stations or transmitting sets for wireless telegraphy and direction findings, and other radio aids to air navigation, using wavelengths in accordance with the rules and regulations made from time to time by the proper agencies of the government. The wireless communication facilities shall be used solely for receiving and transmitting weather forecasts and other matters in connection with the grantee's services."}},{"id":"PH-H6814-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Civil Aeronautics Board. – The grantee shall secure from the Civil Aeronautics Board the appropriate permits and licenses for its operations.\nAll aircraft used by the grantee including their accessories and equipment shall at all times be airworthy and the crew members shall be licensed by the government of the Philippines. They shall be equipped with radio communications, safety and other equipment and shall be operated and maintained in accordance with the regulations and technical requirements of the Air Transportation Office or such other regulatory bodies the government may prescribe for this purpose.\nThe grantee's equipment and the operation of such equipment shall at all times be subject to inspection and regulation by the Air Transportation Office.\nThe grantee shall comply with the provisions of Republic Act Numbered Seven Hundred and Seventy-Six (R.A. No. 776), and the regulation promulgated there under from time to time."}},{"id":"PH-H6814-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Responsibility to the Public. – Excepting cases of force majeure and whenever weather conditions permit, the grantee shall maintain scheduled and/or chartered air transport services to any and all points and places throughout the Philippines and between the Philippines and other countries at such frequencies as traffic needs may require: Provided, however, That at least twenty-five percent (25%) of all its frequencies shall be for the domestic market."}},{"id":"PH-H6814-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Rates for Services. – The grantee shall fix just and reasonable rates for the transportation of passengers, mail, goods and freight, subject to the regulations and approval of the Civil Aeronautics Board and other proper regulatory agencies of the government."}},{"id":"PH-H6814-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to comply with any of the following conditions:\na. Commence operations within one (1) year from the approval of its permit by the Civil Aeronautics Board;\nb. Operate continuously for two (2) years; and\nc. Commence operations within two (2) years from the effectivity of this Act."}},{"id":"PH-H6814-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days after the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Non-acceptance shall render the franchise void."}},{"id":"PH-H6814-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Bond. – The grantee shall file a bond issued in favor of the Civil Aeronautics Board, which shall determine the amount, to guarantee the compliance with and fulfillment of the conditions under which this franchise is granted. If after three (3) years from the date of the approval of its permit by the Board, the grantee shall have fulfilled the same, the bond shall be cancelled by the Board. Otherwise, the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H6814-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Landing Facilities. – The grantee may use the landing and other airport facilities on land and water as may be maintained or owned by the government within the Philippines on the grantee's lines subject to such terms and conditions, restrictions and national policy considerations as the Philippine government may impose: Provided, That the Philippine government shall have the right to use the landing and other airport facilities as may be maintained or owned by the grantee in the Philippines."}},{"id":"PH-H6814-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Contracts. – The grantee is authorized to enter into transportation contracts with the Philippine government, including the carrying of mail, upon such terms and conditions as may be mutually agreed upon. The grantee shall give preferential consideration to contracts with the Philippine government. The grantee may likewise enter into transportation maintenance and/or servicing contracts, and such other contracts relating to air transport with other foreign-owned airlines particularly with those which have international routes."}},{"id":"PH-H6814-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the facilities or equipment of the grantee, to temporarily suspend the operation of any facility or equipment in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said facilities or equipment during the period when they shall be so operated."}},{"id":"PH-H6814-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay the value-added tax under Republic Act No. 7716, as amended, or a franchise tax of five percent (5%) per annum or at such percentage as may be prescribed by law on all gross receipts of its air transport business transacted under this franchise, whichever is higher: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with, and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6814-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the operation of the services under the franchise hereby granted."}},{"id":"PH-H6814-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired there under to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H6814-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Dispersal of Ownership. – In accordance with constitutional provisions to encourage public participation in public utilities, the grantee shall offer at least thirty per centum (30%) of its outstanding capital stock or a higher percentage that may hereafter be provided by law in any securities exchange in the Philippines within five (5) years from the commencement of its operations. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H6814-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Interpretation of Franchise. – This franchise shall not be interpreted to mean as an exclusive grant of the privileges herein provided for. However, in the event that any competing individual, partnership or corporation shall receive a similar permit or franchise with terms and/or provisions more favorable than those herein granted or which tend to place herein grantee at any disadvantage, then such terms and/or provisions shall be deemed part hereof and shall operate equally in favor of the herein grantee."}},{"id":"PH-H6814-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6814-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repealability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6814-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6814-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Air Philippines Corporation (Air Philippines), A Franchise To Establish, Operate and Maintain Domestic and International Air Transport Services","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6815"] = {"id":"PH-H6815","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8340_1997.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"授予 Victorias 电话公司在西内格罗斯省 Victorias 市镇建设、设立、安装、维护和运营本地交换网络的特许经营权法案","en":"An Act Granting the Victorias Telephone System, Inc., A Franchise To Construct, Establish, Install, Maintain and Operate Local Exchange Network in the Municipality of Victorias, Province of Negros Occidental","orig":"An Act Granting the Victorias Telephone System, Inc., A Franchise To Construct, Establish, Install, Maintain and Operate Local Exchange Network in the Municipality of Victorias, Province of Negros Occidental"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8340","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-08-08","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8340_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6815-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Victorias Telephone System, Inc., hereunder referred to as the grantee, its successors or assigns, a franchise to construct, establish, install, maintain and operate for commercial purposes and in the public interest, local exchange network, including public calling stations or pay telephone stations or wireless local loop and for such purpose provide basic telephone service or other means related to the foregoing now known to science or which in the future may be developed in the Municipality of Victorias, Province of Negros Occidental, for public domestic telecommunications."}},{"id":"PH-H6815-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof. In no way shall the operations of the grantee, nor the radiated power of its stations or facilities, exceed that required to cover the area where it is allowed to operate."}},{"id":"PH-H6815-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission, hereinafter referred to as the Commission, a certificate of public convenience or the appropriate permits and licenses for the location, construction, installation and operation of its telecommunications systems. In issuing the certificate, the Commission shall have the power to impose such conditions relative to the construction, operation, maintenance, or service level of the telecommunications system. The Commission shall have the authority to regulate the construction and operation of its telecommunications systems. The grantee shall not use any frequency in the radio spectrum without having been authorized by the Commission. Such certificate shall state the areas covered and date the grantee shall commence the service. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority, permits or licenses."}},{"id":"PH-H6815-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall conform to the ethics of honest enterprise and shall not use its stations for obscene or indecent transmission or for dissemination of deliberately false information or willful misrepresentation, or assist in subversive or treasonable acts.\nThe grantee shall provide basic or enhanced telephone service in any municipality in the Philippines where it has an approved certificate of public convenience for the establishment, operation and maintenance of a local exchange service, without discrimination to any applicant therefor, in the order of the date of their applications, up to the limit of the capacity of its local telephone exchange, and should the demand for the telephone service at any time increase beyond the capacity thereof, the grantee shall increase the same to meet such demand: Provided, That in case the total demand to be satisfied by the expansion is less than the smallest viable local exchange available in the market as determined by the Commission, the grantee shall not be obliged to furnish said service, unless the applicant for telephone service defrays the actual expenses for the installation of the telecommunication apparatus necessary for such services and in such case the Commission may extend the time within which the grantee shall furnish such service.\nThe grantee shall operate and maintain all its stations, lines, cables, systems and equipment for the transmission and reception of messages, signals and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve or change such stations, lines, cables, systems and equipment to keep abreast with the advances in science and technology."}},{"id":"PH-H6815-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Rates for Services. – The charges and rates for telecommunications services of the grantee, except the rates and charges on those that may hereafter be declared or considered as non-regulated services, whether flat rates or measured rates or variation thereof, shall be subject to the approval of the Commission or its legal successors. The rates to be charged by the grantee shall be unbundled, separable and distinct among the services offered and shall be determined in such a manner that regulated services do not subsidize the unregulated ones."}},{"id":"PH-H6815-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations, transmitters, facilities or equipment of the grantee, to temporarily suspend the operation of any station, transmitter, facility or equipment in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations, transmitters, facilities or equipment during the period when they shall be so operated.\nThe radio spectrum is a finite resource that is a part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn anytime, after due process."}},{"id":"PH-H6815-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked, in the event the grantee fails to comply with any of the following conditions:\na. Commence operations within three (3) years from the approval of its operating permit or provisional authority by the National Telecommunications Commission;\nb. Operate continuously for two (2) years; and\nc. Commence operations within five (5) years from the effectivity of this Act."}},{"id":"PH-H6815-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Non-acceptance shall render the franchise void."}},{"id":"PH-H6815-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Bond. – If the grantee is not yet operational, the grantee shall file a bond issued in favor of the National Telecommunications Commission, which shall determine the amount, to guarantee the compliance with and fulfillment of the conditions under which this franchise is granted. If after five (5) years from the date of the approval of its permit by the Commission, the grantee shall have fulfilled the same, the bond shall be cancelled by the Commission. Otherwise, the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H6815-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Right of Interconnection. – The grantee is hereby authorized to connect or demand connection of its telecommunications systems to any other telecommunications systems installed, operated and maintained by any other duly-authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public under such terms and conditions mutually agreed upon by the parties concerned and the same shall be subject to the review or modification of the Commission."}},{"id":"PH-H6815-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay the value-added tax under Republic Act No. 7716 or a franchise tax of three percent (3%) per annum or at such percentage as may be prescribed by law, on all gross receipts of its telecommunications business transacted under this franchise, whichever is higher: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with, and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6815-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Gross Receipts. – The grantee, its successors or assigns, shall keep a separate account of the gross receipts of the business transacted by it and shall furnish the Commission on Audit and the National Treasury a copy of such account not later than the 31st day of January of each year, for the preceding twelve (12) months."}},{"id":"PH-H6815-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Books and Accounts. – The books and accounts of the grantee, its successors or assigns, shall always be open to the inspection of the Commissioner on Audit or his authorized representatives, and it shall be the duty of the grantee to submit to the Commission on Audit, two (2) copies of the quarterly reports on the gross receipts, the net profits and the general condition of the business."}},{"id":"PH-H6815-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, transmitters, facilities and equipment of the grantee."}},{"id":"PH-H6815-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any corporation or entity, nor shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines, except when such person, firm, company, corporation or entity has a valid and existing legislative franchise for telecommunications or it is in pursuance of the provisions of Section 16 of this Act. Any person or entity, to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H6815-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Dispersal of Ownership. – In accordance with the constitutional provisions to encourage public participation in the public utilities, the grantee shall offer at least thirty per centum (30%) of its outstanding capital stock or a higher percentage that may hereafter be provided by law in any securities exchange in the Philippines within ten (10) years from the commencement of its operations or from the effectivity of this Act, whichever is later. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H6815-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6815-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Repealability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6815-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of its franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6815-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Victorias Telephone System, Inc., A Franchise To Construct, Establish, Install, Maintain and Operate Local Exchange Network in the Municipality of Victorias, Province of Negros Occidental","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
