  FT["PH-H6837"] = {"id":"PH-H6837","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8362_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在东内格罗斯省Bayawan市镇设立市镇国立中学，名称为Bayawan国立中学，并为此拨款的法案","en":"An Act Providing For the Establishment of A Municipal National High School in the Municipality of Bayawan, Province of Negros Oriental, To Be Known As the Bayawan National High School, and Appropriating Funds Therefor","orig":"An Act Providing For the Establishment of A Municipal National High School in the Municipality of Bayawan, Province of Negros Oriental, To Be Known As the Bayawan National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8362","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-10-09","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8362_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6837-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a national high school in the Municipality of Bayawan, Province of Negros Oriental, to be known as the Bayawan National High School."}},{"id":"PH-H6837-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6837-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6837-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing For the Establishment of A Municipal National High School in the Municipality of Bayawan, Province of Negros Oriental, To Be Known As the Bayawan National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6838"] = {"id":"PH-H6838","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8363_1997.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将南伊罗戈省 Cabugao Turod 国立中学的名称变更为Cabugao 国立中学的法案","en":"An Act Changing the Name of the Turod National High School in Cabugao, Province of Ilocos Sur, To Cabugao National High School","orig":"An Act Changing the Name of the Turod National High School in Cabugao, Province of Ilocos Sur, To Cabugao National High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8363","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-10-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8363_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6838-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Turod National High School located at Barangay Turod, Municipality of Cabugao, Province of Ilocos Sur, is hereby changed to Cabugao National High School."}},{"id":"PH-H6838-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Turod National High School in Cabugao, Province of Ilocos Sur, To Cabugao National High School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6839"] = {"id":"PH-H6839","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8364_1997.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将新比斯开省 Bayombong 新比斯开科学中学的行政监督权由教育、文化与体育部转归科学技术部","en":"An Act Transferring the Administrative Supervision of the Nueva Vizcaya Science High School in Bayombong, Nueva Vizcaya, From the Department of Education, Culture and Sports To the Department of Science and Technology","orig":"An Act Transferring the Administrative Supervision of the Nueva Vizcaya Science High School in Bayombong, Nueva Vizcaya, From the Department of Education, Culture and Sports To the Department of Science and Technology"},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 8364","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-10-09","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8364_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6839-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The administrative supervision of the Nueva Vizcaya Science High School in Bayombong, Nueva Vizcaya, which was established under Republic Act No. 7622, entitled: \"An Act Establishing the Nueva Vizcaya Science High School in Bayombong, Nueva Vizcaya\" is hereby transferred from the Department of Education, Culture and Sports to the Department of Science and Technology."}},{"id":"PH-H6839-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The high school shall be headed by a director who shall be elected by a Board of Trustees."}},{"id":"PH-H6839-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The regional director, Department of Science and Technology, Region II shall be the chairman of the Board of Trustees of the Nueva Vizcaya Science High School, replacing the regional director, Department of Education, Culture and Sports, Region II, who shall be a member thereof."}},{"id":"PH-H6839-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"On or before the beginning of each school year, the Board of Trustees shall file with the Department of Science and Technology a detailed report setting forth the progress, condition and needs of the high school."}},{"id":"PH-H6839-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Department of Science and Technology shall promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6839-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Transferring the Administrative Supervision of the Nueva Vizcaya Science High School in Bayombong, Nueva Vizcaya, From the Department of Education, Culture and Sports To the Department of Science and Technology","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6840"] = {"id":"PH-H6840","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8365_1997.html","fetchedAt":"2026-10-06","articleCount":29,"structureMode":"ARTICLE","title":{"zh":"将黎刹理工学院改设为国立大学，名称为黎刹理工大学，并为此拨款的法案","en":"An Act Converting the Rizal Technological Colleges Into A State University, To Be Known As the Rizal Technological University, and Appropriating Funds Therefor","orig":"An Act Converting the Rizal Technological Colleges Into A State University, To Be Known As the Rizal Technological University, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8365","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-10-11","completenessNote":"全文，共 29 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8365_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6840-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Rizal Technological Colleges in the City of Mandaluyong, including its branches in the City of Pasig, Municipality of Antipolo in the Province of Rizal, and Municipality of Kawit in the Province of Cavite, is hereby converted into a state university to be known as the Rizal Technological University, hereinafter referred to as the University. The main campus of the University shall be in the City of Mandaluyong."}},{"id":"PH-H6840-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The University shall primarily provide highly professional, scientific, technological, and special instructions in the fields of engineering and technology education, business and entrepreneurial technology, and the arts and sciences. It shall also promote research, extension and advance studies in its areas of specialization.\nThe University shall pursue and endeavor to lead in the development of work-integrated learning through partnership with industry and involvement of students in civic activities. Cooperative education shall provide an important educational component and technical proficiency in the development of human resource capital."}},{"id":"PH-H6840-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The existing high school shall continue to operate as a laboratory for the teacher education programs of the University. The size of its enrollment shall be determined by the Department of Education, Culture and Sports."}},{"id":"PH-H6840-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The University may open new branches in consortium with other academic institutions only within the City of Mandaluyong and the Province of Rizal. For this purpose, the partner concerned shall, in addition to funds appropriated under the regular university budget, provide funds for the infrastructure and manpower needs of the branches thus established, until otherwise provided in the agreement. All properties acquired for the use of the University shall be donated to and titled in the name of the University unless there are legal impediments thereto. Such branches shall offer highly specialized courses in science and technology in accordance with detailed studies on the needs of business, industry and government in the localities to be served. For this purpose, the University President shall appoint a committee to study the feasibility of opening up such branches. Such committee shall include as members, at least a representative each from the business and the industry sector.\nThe University shall, within a reasonable time from the approval of this Act, develop and fully utilize its real property situated in the Municipality of Baras, Province of Rizal, as a site for science and technological researches and agricultural technology projects."}},{"id":"PH-H6840-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The University may enter into agreements with local governments for the support of any of its branches: Provided, That the said agreements shall not in any way impair the autonomy of the University. Under such agreements, the local government shall provide funds to the University in support of university programs in addition to the regular yearly national appropriation of the University. Such funds provided by the local government shall be dealt with in accordance with Section 4 of this Act."}},{"id":"PH-H6840-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The governing body of the University shall be vested in the Board of Regents, hereinafter referred to as the Board, which shall be composed of the following:\na. The Chairman of the Commission on Higher Education (CHED), chairman;\nb. The president of the University, vice chairman;\nc. The chairmen of the Congressional Committees on Education and Culture;\nd. The regional director of the National Economic and Development Authority (NEDA) where the main campus of the University is located;\ne. The president of the federation of faculty associations;\nf. The president of the federation of student councils or the student representative elected by such federation: Provided, That in the absence of a federation president or student representative elected by the federation, the University shall schedule one (1) week for the campaign and election of a student representative;\ng. The president of the federation of alumni associations of the University; and\nh. Two (2) prominent citizens who have distinguished themselves in their professions or fields of specialization, chosen from among a list of at least five (5) qualified persons in the city or province where the school is located, as recommended by the search committee constituted by the President in consultation with the Chairman of the CHED based on the normal standards and qualifications for the position.\nThe private sector representatives shall be appointed by the Board upon recommendation of the duly constituted search committee.\nFor the purpose of paragraphs (f) and (g) of this section, the associations of faculty, alumni, and student councils in each branch of the University shall organize themselves to form their respective federations.\nThe presidents of the federation of faculty associations and alumni associations and the federation of student councils shall sit in the Board until the expiration of their respective terms of office in such capacities.\nThe prominent citizens shall serve for a term of two (2) years."}},{"id":"PH-H6840-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The governing board shall have the following specific powers and duties in addition to its general powers of administration and the exercise of all the powers granted to the board of directors of a corporation under Section 36 of Batas Pambansa Blg. 68, otherwise known as the Corporation Code of the Philippines:\na. To enact rules and regulations not contrary to law, as may be necessary to carry out the purposes and functions of the University;\nb. To receive and appropriate all sums as may be provided, for the support of the University in the manner it may determine, in its discretion, to carry out the purposes and functions of the University;\nc. To receive in trust legacies, gifts and donations of real and personal properties of all kinds, to administer and dispose the same when necessary for the benefit of the University, subject to limitations, directions and instructions of the donors, if any. Such donations shall be exempt from all taxes and shall be considered as deductible items from the income tax of the donor; and\nd. To fix the tuition fees and other school fees and charges, such as, but not limited to, matriculation fees, graduation fees and laboratory fees, as their respective boards may deem proper and reasonable to impose after due consultations with the involved sectors.\nSuch fees and charges, including government subsidies and other income generated by the University, shall constitute special trust funds and shall be deposited in any authorized government depository bank, and all interests that shall accrue therefrom shall form part of the same fund for the use of the University.\nAny provision of existing laws, rules and regulations to the contrary notwithstanding, any income generated by the University from tuition fees and other charges, as well as from the operation of auxiliary services and land grants, shall be retained by the University, and may be disbursed by the Board for instruction, research, extension, or other programs/projects of the University: Provided, That all fiduciary fees shall be disbursed for the specific purposes for which they are collected.\nIf, for reasons beyond its control, the University, shall not be able to pursue any projects for which funds have been appropriated and, allocated under its approved program of expenditures, the Board may authorize the use of said funds for any reasonable purposes which, in its discretion, may be necessary and urgent for the attainment of the objectives and goals of the University;\ne. To adopt and implement a socialized scheme of tuition and school fees for greater access to poor but deserving students;\nf. To authorize the construction or repair of its buildings, machineries, equipment and other facilities and the purchase and acquisition of real and personal properties, including necessary supplies, material and equipment. Purchases and other transactions entered into by the University through the Board shall be exempt from all taxes and duties;\ng. To appoint, upon recommendation of the president of the University, vice presidents, deans, directors and heads of departments faculty members and other officials and employees;\nh. To fix and adjust salaries of faculty members and administrative officials and employees subject to the provisions of the revised compensation and classification system and other pertinent budget and compensation laws governing hours of service, and such other duties and conditions as it may deem proper to; to grant them, at its discretion, leaves of absence under such regulations as it may promulgate, any provisions of existing law to the contrary notwithstanding; and to remove them for cause in accordance with the requirements of due process of law;\ni. To approve the curricula, institutional programs and rules of discipline drawn by the administrative and academic councils as herein provided;\nj. To set policies on admission and graduation of students;\nk. To award honorary degrees upon persons in recognition of outstanding contribution in the field of education, public service, arts, science and technology or in any field of specialization within the academic competence of the University and to authorize the award of certificate of completion of non-degree and non-traditional courses;\nl. To absorb non-chartered tertiary institutions as branches, centers, stations, etc., within the City of Mandaluyong and the Province of Rizal in coordination with the CHED and in consultation with the Department of Budget and Management (DBM), and to offer therein needed programs or courses, to promote and carry out equal access to educational opportunities mandated by the Constitution;\nm. To establish research and extension centers of the University where such will promote the development of the latter;\nn. To establish chairs in the University and to provide fellowships for qualified faculty members and scholarships to deserving students;\no. To delegate any of its powers and duties provided for hereinabove to the president and/or other officials of the University as it may deem appropriate so as to expedite the administration of the affairs of the University;\np. To authorize an external management audit of the institution, to be financed by CHED and to institute reforms, including academic and structural changes, on the basis of audit results and recommendations;\nq. To collaborate with other governing boards of State universities and colleges within the National Capital Region and Region IV, where it may be feasible, under the supervision of the CHED and in consultation with the DBM, the restructuring of said colleges and universities to become more efficient, relevant, productive, and competitive;\nr. To enter into joint ventures with business and industry for the profitable development and management of the economic assets of the University, the proceeds from which shall be used for the development and strengthening of the same;\ns. To develop consortia and other forms of linkages with local government units, institutions and agencies, both public and private, local and foreign, in furtherance of the purposes and objectives of the University;\nt. To develop academic arrangements for institution capability building with appropriate institutions and agencies, public or private, local or foreign, and to appoint experts/specialists as consultants, or visiting or exchange professors, scholars, researchers, as the case may be;\nu. To set up the adoption of modern and innovative modes of transmitting knowledge such as the use of information technology, the dual system, open learning, community laboratory, etc., for the promotion of greater access to higher education;\nv. To establish policy guidelines and procedures for participative decision-making and transparency within the University;\nw. To privatize, where most advantageous to the University, management of non-academic services such as health, food, building, grounds or property maintenance and similar such other activities; and\nx. To extend the term of the president of the University beyond the age of retirement but not later than the age of seventy (70), whose performance has been unanimously rated as outstanding and upon unanimous recommendation by the search committee;"}},{"id":"PH-H6840-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The Board shall regularly convene at least once every quarter. The chairman of the Board may call a special meeting whenever necessary: Provided, That members are notified in writing at least three (3) days prior to said meeting.\nA majority of all members holding office shall constitute a quorum for board meetings: Provided, That the Chairman of the CHED who is the chairman of the Board or the president of the University is among those present in the meeting. In the absence of the Chairman of the CHED, a commissioner of the CHED, duly designated by him, shall represent him in the meeting with all the rights and responsibilities of a regular member: Provided, however, That in the said meeting, the president of the University as the vice chairman shall be the presiding officer.\nThe members shall serve without compensation, but they shall be reimbursed for necessary expenses incurred in their attendance of meetings of the Board or in connection with their official business authorized by resolution of the Board."}},{"id":"PH-H6840-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The administration of the University shall be vested in the president of the University who shall render full-time service. He shall be appointed by the Board, upon recommendation of a duly constituted search committee. He shall have a term of four (4) years and shall be eligible for reappointment for another term.\nIn case of vacancy by reason of death, resignation, removal for cause or incapacity of the president to perform the functions of his office, the Board shall have the authority to designate an officer-in-charge pending the appointment of a new president.\nIn case of vacancy in the office of the president as mentioned in the immediately preceding paragraph, his successor shall hold office for the unexpired term.\nThe powers and duties of the president of the University, in addition to those specifically provided in this Act, shall be those usually pertaining to the office of the president of a similar university, and those delegated by the Board.\nThe salary of the president of the University shall be subject to the existing compensation and position classification system and shall be comparable to that being received by other presidents of similar educational institutions of like standing.\nIn order not to disrupt the operation of the institution and to insure the smooth transition from its status as a college to that of a university, the incumbent president of the College, if qualified, shall serve the unexpired portion of his term as the first president of the new university, subject to the limitations provided herein."}},{"id":"PH-H6840-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"There shall be an administrative council consisting of the president of the University as the chairman, the vice-presidents, deans, directors and other officials of equal rank as members, and whose duty is to review and recommend to the Board policies governing the administration, management and development planning of the University for appropriate action."}},{"id":"PH-H6840-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"There shall be an academic council with the president of the University as chairman and all members of the instructional staff with the rank of not lower than assistant professor, as members.\nThe academic council shall have the power to review and recommend the curricular offerings and rules of discipline of the University subject for appropriate action of the Board. It shall fix the requirements for admission of students as well as for graduation and the conferment of degrees subject to review and/ or approval by the Board."}},{"id":"PH-H6840-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The administrative and academic councils may create standing committees from among its members. The President of the University may appoint an executive committee with the vice-presidents and other members from both councils to act on matters of common concern."}},{"id":"PH-H6840-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"There shall be a secretary of the University who shall be appointed by the Board upon the recommendation of the President of the University. He shall keep such records and exercise such powers as may be determined by the Board. He shall head the University secretariat which shall take charge of the recording and reporting of proceedings of the Board, the administrative and academic councils and the historical events of the University."}},{"id":"PH-H6840-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The Treasurer of the Philippines shall be the ex officio treasurer of the University."}},{"id":"PH-H6840-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"No religious opinion or affiliation shall be a matter of inquiry in the appointment of faculty members of the University: Provided, however, That no member of faculty shall teach for or against any particular church or religious sect."}},{"id":"PH-H6840-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"No student shall be denied admission to the University by reason of sex, nationality, religion, political affiliation, physical handicap, culture, or economic situation."}},{"id":"PH-H6840-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"The University shall enjoy academic freedom."}},{"id":"PH-H6840-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"On or before the fifteenth day of the third month after the opening of the regular classes each year, the Board shall file with the Chairman of CHED and to both Houses of Congress, a detailed report on the progress, conditions and needs of the University."}},{"id":"PH-H6840-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"All assets, fixed and movable, personnel and records of the Rizal Technological Colleges in the City of Mandaluyong and its branches in the City of Pasig, in the Municipality of Antipolo in the Province of Rizal, and in the Municipality of Kawit in the Province of Cavite, as well as liabilities or obligations, are hereby transferred to the University: Provided, however, That the positions, rights and security of tenure of personnel employed therein under existing laws prior to the absorption by the University are not impaired: Provided, further, That the incumbent members of existing position shall remain in the same status until otherwise provided by the Board. All parcels of land belonging to the government and occupied by the Rizal Technological Colleges in the City of Mandaluyong and its existing branches and those previously titled under the name of the Rizal Technological Colleges are hereby declared to be the property of the Rizal Technological University and shall be titled under that name: Provided, finally, That should the University cease to exist or be abolished or should such parcels of land aforementioned be no longer needed by the University, the same shall revert to the provinces, municipalities or cities where they are located."}},{"id":"PH-H6840-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"All accounts and expenses of the University shall be audited by the Commission on Audit or its duly authorized representative."}},{"id":"PH-H6840-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Heads of bureaus and offices of the national government are hereby authorized to loan or transfer, upon request of the president of the University, such apparatus, equipment or supplies as may be needed by the University, and to detail employees for duty therein when, in the judgement of the head of the bureau or office, such apparatus, equipment, supplies or services of such employees can be spared without detriment to the public service. The employees so detailed shall perform such duties as required of them by the president of the University, and the time so employed shall be counted as part of their official service."}},{"id":"PH-H6840-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"It shall be the continuing policy of the University to accept the affiliation and/or integration within its operation of any existing tertiary institutions within the City of Mandaluyong and the Province of Rizal, whose program can contribute largely and effectively to the attainment of its objectives: Provided, however, That in case of integration, the CHED is hereby authorized to determine and approve that the existing tertiary institutions be integrated as part of the University. In this particular case, it is understood that all funds, properties, and other assets as well as obligations of the integrated schools shall be transferred to the University."}},{"id":"PH-H6840-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"The amount needed to carry out the provisions of this Act shall be charged against the current year's appropriations of the Rizal Technological Colleges. Thereafter, such amount as may be necessary for the continued operation and maintenance of the Rizal Technological University shall be included in the annual General Appropriations Act."}},{"id":"PH-H6840-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"The provisions of Republic Act No. 8292, otherwise known as the Higher Education Modernization Act of 1997, shall form as an integral part of this Act and together shall serve as the governing charter of the University."}},{"id":"PH-H6840-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Within a period of one hundred twenty (120) days after the approval of this Act, the University shall accomplish the following:\n1) Submit a five (5) year development plan, including its corresponding program budget, to the CHED, for appropriate recommendation to the DBM;\n2) Undergo a management audit in cooperation with the CHED;\n3) Accordingly set up its organizational, administrative as well as academic, structure, including the appointment/ designation of university key officials; and\n4) Set in motion the establishment of at least four (4) separate degree granting units, one of which is in the arts and sciences and another, at the graduate level."}},{"id":"PH-H6840-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Members of the faculty of the University at the tertiary level, shall be exempt from any civil service examination as a requisite for appointment, without prejudice to the right of the Board to impose other professional examination requirements intended to maintain high academic standards."}},{"id":"PH-H6840-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"All other powers, functions, privileges, responsibilities and limitations to state universities and/or its officials under existing laws shall be deemed granted to or imposed upon the University and/or its officials whenever appropriate."}},{"id":"PH-H6840-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"All laws, presidential decrees, executive orders, rules and regulations contrary to or inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H6840-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Rizal Technological Colleges Into A State University, To Be Known As the Rizal Technological University, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6841"] = {"id":"PH-H6841","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8366_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"放宽菲律宾投资公司业，为此修订经修正的第129号总统令（即《投资公司法》）若干条款的法案","en":"An Act Liberalizing the Philippine Investment House Industry, Amending Certain Sections of Presidential Decree No. 129, as amended, otherwise known as the Investment Houses Law","orig":"An Act Liberalizing the Philippine Investment House Industry, Amending Certain Sections of Presidential Decree No. 129, as amended, otherwise known as the Investment Houses Law"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8366","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-10-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8366_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6841-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of policy. – It is the policy of the State to expand and strengthen the capital base of the economy in order to ensure sustained economic growth and development. Toward this end, the Philippine investment house industry is hereby liberalized, increasing foreign equity participation and raising the minimum capitalization of investment houses to enable them to meet the present and future demands of the market."}},{"id":"PH-H6841-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Sec. 5 of Presidential Decree No. 129, as amended, otherwise known as the Investment Houses Law, is hereby further amended, to read as follows:\n\"Sec. 5. Citizenship requirements. – At least forty percent (40%) of the voting stock of any Investment House shall be owned by citizens of the Philippines. In determining the percentage of foreign-owned voting stocks in Investment Houses, the basis for the computation shall be the citizenship of each stockholder, and, if the stockholder is a corporation, the citizenship of the individual stockholders holding voting shares in that corporation. In approving foreign equity applications in Investment Houses, the Securities and Exchange Commission shall approve such applications only if the same or similar rights are enjoyed by Philippine nationals in the applicant's country.\n\"Foreign nationals may become members of the board of directors to the extent of the foreign participation in the equity of said enterprise.\""}},{"id":"PH-H6841-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Sec. 8 of the same Decree is hereby amended to read as follows:\n\"Sec. 8. Capital requirements. – In the case of newly-organized Investment Houses, the minimum paid-in capital shall be Three hundred million pesos (P300,000,000). The minimum paid-in capital of the existing Investment Houses shall be Three hundred million pesos (P300,000,000) to be built up in two (2) years after the effectivity of this Act in the following manner: Two hundred million pesos (P200,000,000) after the effectivity of this Act and an additional Fifty million pesos (P50,000,000) for every year thereafter until the minimum capitalization is attained. The Monetary Board may prescribe a higher minimum capitalization in order to promote and ensure the stability of the Philippine capital market and the competitiveness of the investment house industry in line with the national economic goals. The Monetary Board shall, within six (6) months, prescribe a risk assets to capital ratio and other capital adequacy ratios in order to provide broader protection to the investing public.\""}},{"id":"PH-H6841-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days from its publication in a newspaper of general circulation."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Liberalizing the Philippine Investment House Industry, Amending Certain Sections of Presidential Decree No. 129, as amended, otherwise known as the Investment Houses Law","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6842"] = {"id":"PH-H6842","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8367_1997.html","fetchedAt":"2026-10-06","articleCount":31,"structureMode":"ARTICLE","title":{"zh":"1997 年经修订的非股份储蓄与贷款协会法","en":"Revised Non-Stock Savings and Loan Association Act of 1997","orig":"Revised Non-Stock Savings and Loan Association Act of 1997 An Act Providing for the Regulation of the Organization and Operation of Non-Stock Savings and Loan Associations"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8367","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-10-21","completenessNote":"全文，共 31 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8367_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6842-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – The short title of this Act shall be the \"Revised Non-Stock Savings and Loan Association Act of 1997\"."}},{"id":"PH-H6842-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of policy. – It is hereby declared the policy of the State to:\na) encourage industry, frugality and the accumulation of savings, and judicious utilization of credit among the members of non-stock savings and loan associations;\nb) regulate and supervise the activities of non-stock savings and loan associations in order to place their operations on a sound, stable, and efficient basis to the end that they may be able to better provide for the establishment of additional savings and credit facilities in a fair manner to their members and to curtail or prevent acts or practices of these Associations which are prejudicial to their members' interest;\nc) lay down the minimum requirements and the standards under which non-stock savings and loan Associations may organize and operate; and\nd) maximize the protection of members of non-stock savings and loan associations against misfeasance and malfeasance of the trustees and officers thereof."}},{"id":"PH-H6842-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of terms. – For the purposes of implementing this Act, the following definitions shall apply:\na) Non-stock savings and loan association shall mean a non-stock, non-profit corporation engaged in the business of accumulating the savings of its members and using such accumulations for loans to members to service the needs of households by providing long term financing for home building and development and for personal finance;\nb) Association shall refer only to non-stock savings and loan associations organized under this Act and the Corporation Code of the Philippines;\nc) Monetary Board shall mean the Monetary Board of the Bangko Sentral ng Pilipinas; and\nd) Bangko Sentral shall mean the Bangko Sentral ng Pilipinas."}},{"id":"PH-H6842-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Organization of an Association. – At least five (5) but not more than fifteen (15) members of a well-defined group as provided herein may form an Association under this Act. An Association, prior to transacting any business, shall secure a license from the Monetary Board and register with the Securities and Exchange Commission (SEC). The application for a license, signed by a majority of the incorporators and verified by one of the trustees, shall include:\na) the proposed articles of incorporation and bylaws together with names and addresses of the incorporators, trustees and officers, with a statement of their character, experience and general fitness to engage in the non-stock savings and loan business;\nb) an itemized statement of the estimated receipts and expenditures of the proposed Association for the first year;\nc) a filing fee in such amount as may be determined by the Monetary Board; and\nd) such other information as the Monetary Board may require.\nThe SEC shall not register the articles of incorporation and bylaws of a proposed Association unless the application is accompanied by a certificate of the Monetary Board approving the same. The Monetary Board may deny the application to organize an Association under this Act if it finds that the Association is being organized for any purpose other than to engage in the business of a legitimate non-stock savings and loan association or that the Association's financial program is unsound, or that the proposed members are adequately served by one or more existing Associations.\nThe Association shall confine its membership to a well-defined group of persons and shall not transact business with the general public. A \"well-defined group\" shall be defined by the Monetary Board, and shall consist of, but not be limited to, any of the following:\n1) employees, officers, and directors of one company, including member-retirees;\n2) government employees belonging to the same department/branch/office, including member-retirees; and\n3) immediate members of the families (up to second degree of consanguinity or affinity) of those falling under paragraphs 1 and 2 above.\nAssociations whose articles of incorporation and bylaws were approved and registered prior to the effectivity of this Act and which allow membership coverage broader than the foregoing definition, shall be allowed to continue as such, unless otherwise required by the Monetary Board.\nThe Monetary Board may, as circumstances warrant, require Associations mentioned in the immediately preceding paragraph to amend their bylaws to comply with the concept of a \"well-defined group.\"\nIn no case shall the total amount of entrance fees exceed one percent (1%) of the amount to be contributed or otherwise paid in by the particular member: Provided, That for new members, the said fee shall be based on the amount of contribution computed in accordance with the revaluation of the assets of the Association.\nNo person, association, partnership or corporation shall do business, or hold itself out as doing business, as an Association, or shall use the term \"Savings and Loan Association\" or any other title or name tending to give the public the impression that it is engaged in the operations and activities of an Association, unless so authorized under this Act."}},{"id":"PH-H6842-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Tax exemption. – An Association shall be exempt from payment of tax in respect to income it receives, including interest on its deposits with any bank: Provided, however , That income derived from any of its properties, real or personal, or any activity conducted for profit, regardless of the disposition thereof, is subject to the corresponding internal revenue taxes imposed under the National Internal Revenue Code.\nInterest earnings on deposits of members with Associations as well as the shares of its members from the net income of the Associations shall be exempt from income tax."}},{"id":"PH-H6842-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Prohibition against inquiry into or disclosure of deposits. – All deposits of whatever nature with an Association in the Philippines are hereby considered as of an absolutely confidential nature and may not be examined, inquired or looked into by any person, government official, bureau or office, except upon written permission of the depositor, or in cases of impeachment, or upon order of a competent court in cases of bribery or dereliction of duty of public officials, or in cases where the money deposited or invested is the subject matter of litigation.\nIt shall be unlawful for any official or employee of an Association to disclose to any person any information concerning said deposits, except in the cases mentioned in the preceding paragraph of this Sec.. Any official or employee of an Association who violates this Sec. shall be punished under Republic Act No. 1405, as amended."}},{"id":"PH-H6842-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Powers of Associations. – The Association shall accept deposits from and grant loans only to its members, subject to such rules and regulations as the Monetary Board may promulgate to ensure sound, stable and efficient operation: Provided, That no deposits shall be sourced or deducted from the loans granted to a member without his or her written consent.\nThe loans shall not exceed the members' deposits and contributions in the Association, plus twelve (12) months of his regular salary as the Association may allow or seventy percent (70%) of the fair market value of any property acceptable as collateral on first mortgage that he may offer as security: Provided, That no loan shall have the maturity date of more than five (5) years, except loans on the security of unencumbered real estate for the purpose of home building and home development, which may be granted with maturities not exceeding twenty-five (25) years, and medium and long-term loans to finance agricultural projects, subject to regulations prescribed by the Monetary Board: Provided, further , That the treasurer, cashier, or paymaster of the office employing a member is required, notwithstanding the provision of any existing law, rule and regulation to the contrary, to make deductions from his salary, wage, income or retirement pension pursuant to the terms of his loan, and all other deductions authorized by the member, to remit such deductions to the Association concerned, and to collect such reasonable fee for his services as may be authorized by rules promulgated by the Monetary Board.\nIn addition to the powers granted it by this Act and existing laws, any Association may:\na) charge reasonable interest and collect such necessary fees and charges incidental to the grant of loans;\nb) invest its funds in any sound non-speculative enterprises as well as in bonds, security, and other obligations issued by the Government of the Philippines, or any of its political subdivisions, instrumentalities, or corporations including government-owned or -controlled corporations, subject to the rules and regulations of the Monetary Board;\nc) allow members to participate in the profits of the Association;\nd) borrow money or incur such obligations not exceeding twenty percent (20%) of the total assets of the Association, from any lending institution. The Monetary Board, may, in meritorious cases, raise the ceiling on the borrowing capacity of an Association to an amount not exceeding thirty percent (30%) of its total assets: Provided, That any such Association organized by employees of an entity or corporation may borrow funds from said entity or corporation but not vice-versa: Provided, further , That the number of the Association's creditors shall not exceed nineteen (19) at any one time;\ne) maintain deposits with banks: Provided, That the amount of such deposits shall be subject to the loan limit to a single borrower as prescribed herein or by other special laws or regulations;\nf) require the employer-entity or corporation to provide it with adequate office space within which it can conduct its business; and\ng) engage in death benefit program meant exclusively for the mutual benefit of its members."}},{"id":"PH-H6842-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Restrictions on Associations. – a) No Association shall have or carry upon its books for any person any demand, commercial or checking account, or any credit to be withdrawn upon the presentation of any negotiable check or draft.\nb) No Association shall advertise or represent itself to the public as a bank.\nc) No Association shall issue, publish or cause or permit to be issued or published, any advertisement that it is doing or permitted to do any business which is prohibited by law for an Association."}},{"id":"PH-H6842-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Service units. – An Association shall open, maintain and operate service units as may be necessary in order to deliver services to its members subject to approval of the Monetary Board."}},{"id":"PH-H6842-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Agents and salesmen. – No person shall act as an agent or sales representative of an Association or operate an agency without obtaining a license from the Monetary Board. No license is required for a collector of an Association but no person shall hold himself out or act as collector unless he is authorized as a collector in writing by such Association."}},{"id":"PH-H6842-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Merger or consolidation of Associations. – To achieve simplicity, economy and efficiency, different associations of one company or department or office may merge or consolidate upon approval of the Monetary Board."}},{"id":"PH-H6842-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Trustees. – Only members are eligible as trustees of an Association: Provided, That in the case of a merger or consolidation of Associations duly approved by the Monetary Board, the limitation on the maximum number of trustees in a corporation, as provided for in the Corporation Code, shall not be applied for a maximum period of three (3) years so that membership in the new board may include up to the total number of trustees provided for in the respective articles of incorporation of the merging or consolidating Associations."}},{"id":"PH-H6842-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Bond of officers and employees. – All officers and employees of an Association who, in the regular discharge of their duties have access to money or negotiable securities shall, before entering upon such duties, furnish to the employing Association a good and sufficient bond, the form and amount of which shall be prescribed by the Monetary Board, and providing for indemnity to the Association against the loss of money or securities, by reason of their dishonesty."}},{"id":"PH-H6842-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Compensation of trustees, officers and employees. – No trustee, officer, or employee of an Association shall receive from such Association, and no Association shall pay to any trustee, officer, or employee of such Association, any commission, emolument, gratuity or reward based on the volume or number of loans made, or based on the interest or fees collected thereon. Nothing in this Sec. prohibits or limits any of the following:\na) receipt or payment of salaries of trustees, officers and employees;\nb) receipt of payment of commissions to agents whether or not based on the volume or number of loans or on the interest or fees collected thereon; and\nc) receipt or payment of bonuses to trustees, officers or employees if such bonuses are based on the performance and not on the volume or number of loans made or on the interest or fees collected thereon.\nAll increase in the compensation, in any form, of all trustees and trustee-officers in excess of ten percent (10%) thereof per annum shall require the approval of the Bangko Sentral."}},{"id":"PH-H6842-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Limitations on lending authority. – a) An Association shall not commit itself to make any loans for amounts in excess of the total of the following amounts:\n1) amount of cash available for loan purposes;\n2) amount of cash which can be readily realized upon the sale or redemption of permissible investments made by the Association; and\n3) amount of credit available for loan purposes from government or private financing institutions.\nb) No Association shall directly or indirectly make any loans to any trustee or officer of such Association, either for himself or as agent or as partner of another, except with the written approval of the majority of the trustees of the Association, excluding the trustee concerned: Provided , That the total loans, direct or indirect, granted at any one time to such trustees and officers shall not exceed twenty percent (20%) of the total capital contributions of the Association; in all cases of the credit accommodations granted to trustees and officers under this subSec., the written approval of the majority of the trustees of the Association, excluding the trustee concerned, shall be entered upon the records of the Association and a copy of such entry shall be transmitted forthwith to the Bangko Sentral.\nThe transactions of all trustee-officers with the Association shall not be under terms more favorable than those transacted with other members. The office of any trustee or trustee-officer of an Association who violates the provisions of this subSec. shall immediately become vacant and the trustees or officers shall be punished by imprisonment of not less than one (1) year nor more than ten (10) years and by a fine of not less than Five thousand pesos (P5,000) nor more than Fifty thousand pesos (P50,000)."}},{"id":"PH-H6842-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Execution of loan agreement. – For each loan made by an Association, a written note or other obligation expressing a rate of interest must be executed by the borrower."}},{"id":"PH-H6842-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Liability of officers for loans contrary to law. – No Association shall make or purchase any loan or investment not authorized or permitted under this Act, and any trustee, officer or employee, who on behalf of any such Association, knowingly makes or purchases any such loan or investment or who knowingly consents thereto shall be personally liable to the Association for the full amount of any such loan or investment."}},{"id":"PH-H6842-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Limitations on investment. – a) No Association at any one time shall invest in bonds and securities in a total amount in excess of ten percent (10%) of the total assets of such Association without prior written approval of the Bangko Sentral.\nb) No Association at any one time shall invest in real property in a total amount in excess of five percent (5%) of the total assets of such Association.\nc) No Association at any one time shall invest in furniture, fixture, furnishings and equipment and leasehold improvements for its offices, in an amount more than ten percent (10%) of its total capital contribution."}},{"id":"PH-H6842-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Reserves. – Every Association shall create a withdrawable share reserve which shall consist of two percent (2%) of the total capital contributions of the members which the Monetary Board may increase to a maximum of three percent (3%), as the situation warrants.\nNo Association shall distribute to its members any portion of its net income if its withdrawable share reserve is less than the minimum requirement, or if by such payment or distribution, such reserve will be reduced to an amount below the minimum requirement provided herein."}},{"id":"PH-H6842-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Withdrawal by a member. – For the sole purpose of allowing an equitable valuation and distribution of assets for withdrawing members, an Association shall, upon the effectivity of this Act, impute revalued surplus to be added to the withdrawn capital, subject to such rules as the Monetary Board may prescribe. Such rules shall allow a reasonable period between withdrawal of capital and payment of the share of the member from the revalued surplus."}},{"id":"PH-H6842-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Annual reports by the Association. – Every Association shall, within one hundred twenty (120) calendar days after the close of its fiscal year furnish the Monetary Board and post in any of the Association's bulletin board or in any other conspicuous place a copy of its financial statement showing, in such form and detail as the Monetary Board shall require, the amount and character of the assets and liabilities of the Association at the end of the preceding fiscal year. The Monetary Board may, in addition to the foregoing, require the disclosure of such other information as it shall deem necessary for the protection of the members of the Association."}},{"id":"PH-H6842-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Regulatory powers over Associations. – Notwithstanding the provisions of Sec. 130 of Republic Act No. 7653, the power to regulate the operations of any Association by the Monetary Board shall continue and consist of the following:\na) in seeing to it that the capital, financing, direction and administration, as well as the integrity, responsibility, and ability of organizers, administrators, trustees, and officers of all Associations organized and operated under this Act, shall reasonably assure the safety of the interests which its members entrust to them;\nb) in regulating the operation and activities of Associations, which include, among others: 1) in placing limits to the maximum credit allowed any individual borrower; 2) in determining the loan repayment period and loan procedures; 3) in imposing a uniform accounting system and manner of keeping the accounts and records of Associations; 4) in instituting periodic surveys of loan and lending procedures, audits, test check of each and other transactions of Associations; and 5) whenever necessary, in conducting training courses for personnel of Associations;\nc) in requiring all accountable officers and employees of every Association to post bonds for the faithful performance of their duties in reasonable sums and with such sureties as the Monetary Board may require;\nd) in fixing, by rules or by orders, in specific cases, after notice and hearing, the limits of loanable funds, amounts for investment and reserves for withdrawals and other contingencies;\ne) in issuing rules and regulations for the proper implementation of this Act, effective administration of the Associations, and to render advisory assistance to all interested parties in order to carry out the intents and purposes of this Act; and\nf) in conducting such investigations, taking such remedial measures and exercising all powers under Republic Act No. 7653, insofar as they are applicable in the enforcement of this Act.\nThe Bangko Sentral shall have the power to enforce the laws, orders, instructions, rules and regulations promulgated by the Monetary Board applicable to Associations; to require Associations, their trustees, officers and agents to conduct and manage the affairs of the Association in a lawful and orderly manner. After due notice and hearing, the Monetary Board may revoke or suspend the license of any Association, for such period as it determines necessary, particularly when the solvency of an Association is imperiled by losses or irregularities, and/or when an Association willfully violates any provisions of this Act or any rule or regulations promulgated hereunder.\nThe director and examiners of the department of the Bangko Sentral charged with the regulation of Associations are hereby authorized to administer oaths to any trustee, officer or employee of any Association or to any voluntary witness and to compel the presentation of all books, documents, papers or records necessary in his judgment to ascertain the facts relative to the true condition of any Association or to any loan."}},{"id":"PH-H6842-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Penalties. – a) The provisions of Sec. 34 of Republic Act No. 7653 shall apply to any agent, manager, or other officer-in-charge of any Association who willfully refuses any lawful examination into the affairs of such Association.\nb) The willful making of a false statement or misleading statement on a material fact to the Monetary Board or to the director of the department of the Bangko Sentral charged with the regulation of Associations or to his examiners shall be punished in accordance with Sec. 35 of Republic Act No. 7653.\nc) Whenever any Association, person or entity willfully violates this Act or any order, instruction, rule or regulation issued by the Monetary Board applicable to Associations, the persons responsible for such violation shall be punished in accordance with Sec. 36 of Republic Act No. 7653.\nd) Whenever any officer, employee, or agent of an Association accepts gifts, fees or commissions or any other form of remuneration in connection with the approval of a loan from said Association; or overvalues or aids in overvaluing any security for the purpose of influencing in any way the action of the Association on any loan, such officer, employee or agent shall be punished by a fine of not more than Ten thousand pesos (P10,000) or three times the loan amount involved, whichever is higher, or imprisonment for not more than one (1) year, at the discretion of the court.\ne) Whenever any applicant for a loan, or borrower of an Association fraudulently overvalues property offered as security for loan from the said Association; or furnishes false, or makes willful misrepresentation of material facts for the purpose of obtaining, renewing, or increasing a loan or extending the period thereof; or attempts to defraud the said Association in the event of a court action to recover a loan; or offers any officer, of a court action to recover a loan; or offers any officer, employee or agent of an Association any gift, fee, commission, or other form of compensation in order to influence such Association personnel into approving a loan application; such applicant or borrower shall be punished by a fine of not more than Five thousand pesos (P5,000) or three times the loan amount involved, whichever is higher, or imprisonment for not more than one (1) year, at the discretion of the court.\nf) Whenever any examiner, officer or employee of the Bangko Sentral, who is assigned to examine, assist or render technical service to an Association, overvalues or aids in overvaluing any security for the purpose of influencing in any way the action of the Association on any loan or connives or aids in the commission of the same, he shall be punished by a fine of not more than Ten thousand pesos (P10,000) or three times the loan amount involved, whichever is higher, or imprisonment for not more than one (1) year, at the discretion of the court."}},{"id":"PH-H6842-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Annual fees. – Consistent with the provisions of Sec. 28 of Republic Act No. 7653, any Association organized under this Act may, pursuant to regulations promulgated for the purpose by the Monetary Board, be required to contribute to the Bangko Sentral an annual fee to be determined by the Monetary Board."}},{"id":"PH-H6842-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Implementation. – For the purpose of carrying the objectives of this Act, the Bangko Sentral is authorized to require the services and facilities of any department or instrumentality of the government or any officer or employee of any such department or instrumentality."}},{"id":"PH-H6842-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Annual report of the Monetary Board. – The Monetary Board shall submit a report to the Congress of the Philippines as of the end of each calendar year of all the rules and regulations promulgated by it in accordance with the provisions of this Act, together with the explanations of its reasons therefor."}},{"id":"PH-H6842-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Industry Association. – Membership in an existing association of Associations duly accredited and recognized by the Bangko Sentral, is hereby encouraged."}},{"id":"PH-H6842-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Applicability of other laws. – The provisions of Republic Act No. 7653 and Republic Act No. 337, as amended, insofar as they are applicable and not in conflict with any provision of this Act, shall apply to Associations organized hereunder."}},{"id":"PH-H6842-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Separability clause. – If any provision of this Act or the application thereof to any persons or circumstances is held invalid, the other provisions of this Act and the application of such provisions to other persons and circumstances, shall not be affected thereby."}},{"id":"PH-H6842-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Repealing clause. – Republic Act No. 3779, as amended, is hereby repealed. Any law or parts of law inconsistent with the provisions of this Act are hereby repealed. In all matters affecting the price stability of the peso, the provisions of Republic Act No. 7653 shall prevail."}},{"id":"PH-H6842-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days following the completion of its publication in the Official Gazette or in two (2) national newspapers of general circulation."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Revised Non-Stock Savings and Loan Association Act of 1997","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6843"] = {"id":"PH-H6843","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8368_1997.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"废止总统令 No","en":"Penalizing Squatting and other Similar Acts","orig":"Anti-Squatting Law Repeal Act of 1997 An Act Repealing Presidential Decree No. 772, Entitled \"Penalizing Squatting and other Similar Acts\""},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 8368","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-10-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8368_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6843-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – This Act shall be known as the \"Anti-Squatting Law Repeal Act of 1997.\""}},{"id":"PH-H6843-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Repeal. – Presidential Decree No. 772, entitled \"Penalizing Squatting and Other Similar Acts\" is hereby repealed."}},{"id":"PH-H6843-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Effect on pending cases. – All pending cases under the provisions of Presidential Decree No. 772 shall be dismissed upon the effectivity of this Act."}},{"id":"PH-H6843-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effect on Republic Act No. 7279. – Nothing herein shall be construed to nullify, eliminate or diminish in any way Sec. 27 of Republic Act No. 7279 or any of its provisions relative to sanctions against professional squatters and squatting syndicates."}},{"id":"PH-H6843-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. – This Act shall take effect thirty (30) days after its publication in two (2) newspapers of national circulation."}}],"pack":"ph-p97"};
  FT["PH-H6844"] = {"id":"PH-H6844","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8369_1997.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"1997 年家庭法院法","en":"Family Courts Act of 1997","orig":"Family Courts Act of 1997 An Act Establishing Family Courts, Granting Them Exclusive Original Jurisdiction Over Child and Family Cases, Amending Batas Pambansa Bilang 129,As Amended, Otherwise Known as Act of 1980, Appropriating Funds Therefor and for Other Purposes"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 8369","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-10-28","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8369_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6844-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. - This Act shall be known as the \"Family Courts Act of 1997\"."}},{"id":"PH-H6844-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Statement of National Policies. - The State shall protect the rights and promote the welfare of children in keeping with the mandate of the Constitution and the precepts of the United Nations Convention on the rights of the Child. The State shall provide a system of adjudication for youthful offenders which takes into account their peculiar circumstances.\nThe State recognizes the sanctity of family life and shall protect and strengthen the family as a basic autonomous social institution. The courts shall preserve the solidarity of the family, provide procedures for the reconciliation of spouses and the amicable settlement of family controversy."}},{"id":"PH-H6844-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Establishment of Family Courts. - There shall be established a Family Court in every province and city in the country. In case where the city is the capital of the province, the Family Court shall be established in the municipality which has the highest population."}},{"id":"PH-H6844-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Qualification and Training of Family Court Judges. - Sec. 15 of Batas Pambansa Blg. 129, as amended, is hereby further amended to read as follows:\n\"Sec. 15. (a) Qualification. - No person shall be appointed Regional Trial Judge or Presiding Judge of the Family Court unless he is a natural-born citizen of the Philippines, at least thirty-five (35) years of age, and, for at least ten (10) years, has been engaged in the practice of law in the Philippines or has held a public office in the Philippines requiring admission to the practice of law as indispensable requisite.\n\"(b) Training of Family Court Judges. - The Presiding Judge, as well as the court personnel of the Family Courts, shall undergo training and must have the experience and demonstrated ability in dealing with child and family cases.\n\"The Supreme Court shall provide a continuing education program on child and family laws, procedure and other related disciplines to judges and personnel of such courts.\""}},{"id":"PH-H6844-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Jurisdiction offamily Courts. - The Family Courts shall have exclusive original jurisdiction to hear and decide the following cases:\na) Criminal cases where one or more of the accused is below eighteen (18) years of age but not less than nine (9) years of age but not less than nine (9) years of age or where one or more of the victims is a minor at the time of the commission of the offense: Provided, That if the minor is found guilty, the court shall promulgate sentence and ascertain any civil liability which the accused may have incurred.\nThe sentence, however, shall be suspended without need of application pursuant to Ptesidential Decree No. 603, otherwise known as the \"Child and Youth Welfare Code\";\nb) Petitions for guardianship, custody of children, habeas corpus in relation to the latter;\nc) Petitions for adoption of children and the revocation thereof;\nd) Complaints for annulment of marriage, declaration of nullity of marriage and those relating to marital status and property relations of husband and wife or those living together under different status and agreements, and petitions for dissolution of conjugal partnership of gains;\ne) Petitions for support and/or acknowledgment;\nf) Summary judicial proceedings brought under the provisions of Executive Order No. 209, otherwise known as the \"Family Code of the Philippines\" ;\ng) Petitions for declaration of status of children as abandoned, dependent o neglected children, petitions for voluntary or involuntary commitment of children; the suspension, termination, or restoration of parental authority and other cases cognizable under Presidential Decree No. 603, Executive Order No. 56, (Series of 1986), and other related laws;\nh) Petitions for the constitution of the family home;\n(i) Cases against minors cognizable under the Dangerous Drugs Act, as amended;\nj) Violations of Republic Act No. 7610, otherwise known as the \"Special Protection of Children Against Child Abuse, Exploitation and Discrimination Act,\" as amended by Republic Act No. 7658; and\nk) Cases of domestic violence against:\n1) Women - which are acts of gender based violence that results, or are likely to result in physical, sexual or psychological harm or suffering to women; and other forms of physical abuse such as battering or threats and coercion which violate a woman's personhood, integrity and freedom movement; and\n2) Children - which include the commission of all forms of abuse, neglect, cruelty, exploitation, violence, and discrimination and all other conditions prejudicial to their development.\nIf an act constitutes a criminal offense, the accused or batterer shall be subject to criminal proceedings and the corresponding penalties.\nIf any question involving any of the above matters should arise as an incident in any case pending in the regular courts, said incident shall be determined in that court."}},{"id":"PH-H6844-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Use of Income. - All Family Courts shall be allowed the use of ten per cent (10%) of their income derived from filing and other court fees under Rule 141 of the Rules of Court for research and other operating expenses including capital outlay: Provided, That this benefit shall likewise be enjoyed by all courts of justice.\nThe Supreme Court shall promulgate the necessary guidelines to effectively implement the provisions of this Sec."}},{"id":"PH-H6844-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Special Provisional Remedies. - In cases of violence among immediate family members living in the same domicile or household, the Family Court may issue a restraining order against the accused of defendant upon verified application by the complainant or the victim for relief from abuse.\nThe court may order the temporary custody of children in all civil actions for their custody. The court may also order support pendente lite, including deduction from the salary and use of conjugal home and other properties in all civil actions for support."}},{"id":"PH-H6844-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Supervision of Youth Detention Homes. - The judge of the Family Court shall have direct control and supervision of the youth detention home which the local government unit shall establish to separate the youth offenders from adult criminals: Provided, however, That alternatives to detention and institutional care shall be made available to the accused including counseling, recognizance, bail, community continuum, or diversions from the justice system: Provided, further, That the human rights of the accused are fully respected in a manner appropriate to their well-being."}},{"id":"PH-H6844-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Social Services and Counseling Division. - Under the guidance ofthe Department of Social Welfare and Development (DSWD), a Social Services and Counseling Division (SSCD) shall be established in each judicial region as the Supreme Court shall deem necessary based on the number of juvenile and family cases existing in such jurisdiction. It shall provide appropriate social services to all juvenile and family cases filed with the court and recommend the proper social action. It shall also develop programs, formulate uniform policies and procedures, and provide technical supervision and monitoring of all SSCD in coordination with the judge."}},{"id":"PH-H6844-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Social Services and Counseling Division Staff. - The SSCD shall have a staff composed of qualified social workers and other personnel with academic preparation in behavioral sciences to carry out the duties'of conducting intake assessment, social case studies, casework and counseling, and othersocial services that may be needed in connection with cases filed with the court: Provided, however, That in adoption cases and in petitions for declaration of abandonment, the case studies may be prepared by social workers of duly licensed child caring or child placement agencies, or the DSWD. When warranted, the division shall recommend that the court avail itself of consultative services of psychiatrists, psychologists, and other qualified specialists presently employed in other departments of the government in connection with its cases.\nThe position of Social Work Adviser shall be created under the Office of the Court Administrator, who shall monitor and supervise the SSCD ofthe Regional Trial Court."}},{"id":"PH-H6844-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Alternative Social Services. - In accordance with Sec. 17 of this Act, in areas where no Family Court has been established or no Regional Trial Court was designated by the Supreme Court due to the limited number of cases, the DSWD shall designate and assign qualified, trained, and DSWD accredited social workers of the local government units to handle juvenile and family cases filed in the designated Regional Trial Court of the place."}},{"id":"PH-H6844-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Privacy and Confidentiality of Proceedings. - All hearings and conciliation of the child and family cases shall be treated in a manner consistent with the promotion of the child's and the family's dignity and worth, and shall respect their privacy at all stages of the proceedings. Records of the cases shall be dealt with utmost confidentiality and the identity of parties shall not be divulged unless necessary and with authority of the judge."}},{"id":"PH-H6844-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Special Rules of Procedure. - The Supreme Court shall promulgate special rules of procedure for the transfer of cases to the new courts during the transition period and for the disposition of family cases with the best interests of the child and the protection of the family as primary consideration taking into account the United Nations Convention on the Rights of the Child."}},{"id":"PH-H6844-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Appeals. - Decisions and orders of the court shall be appealed in the same manner and subject to the same conditions as appeals from the ordinary Regional Trial Courts."}},{"id":"PH-H6844-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Appropriations. - The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following in its enactment into law and thereafter."}},{"id":"PH-H6844-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Implementing Rules and Regulations. - The Supreme Court, in coordination with the DSWD, shall formulate the necessary rules and regulations for the effective implementation of the social aspects of this Act."}},{"id":"PH-H6844-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Transitory Provisions. - Pending the establishment of such Family Courts, the Supreme Court shall designate from among the branches ofthe Regional Trial Court at least one Family Court in each of the cities of Manila, Quezon, Pasay, Caloocan, Makati, Pasig, Mandaluyong, Muntinlupa, Laoag, Baguio, Santiago, Dagupan, Olongapo, Cabanatuan, San Jose, Angeles, Cavite, Batangas, Lucena, Naga, Iriga, Legazpi, Roxas, Iloilo, Bacolod, Dumaguete, Tacloban, Cebu, Mandaue, Tagbilaran, Surigao, Butuan, Cagayan de Oro, Davao, General Santos, Oroquieta, Ozamis, Dipolog, Zamboanga, Pagadian, Iligan, and in such other places as the Supreme Court may deem necessary.\nAdditional cases other than those provided in Sec. 5 may be assigned to the Family Courts when their dockets permit: Provided, That such additional cases shall not be heard on the same day family cases are heard.\nIn areas where there are no Family Courts, the cases referred to in Sec. 5 of this Act shall be adjudicated by the Regional Trial Court."}},{"id":"PH-H6844-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Separability Clause. - In case any provision of this Act is declared unconstitutional, the other provisions shall remain in effect."}},{"id":"PH-H6844-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Repealing Clause. - All other laws, decrees, executive orders, rules or regulations inconsistent herewith are hereby repealed, amended or modified accordingly."}},{"id":"PH-H6844-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Family Courts Act of 1997","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6845"] = {"id":"PH-H6845","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8370_1997.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"1997 年儿童电视法","en":"Children's Television Act of 1997","orig":"Children's Television Act of 1997"},"level":"law","status":"active","topics":["civil"],"docNumber":"Republic Act No. 8370","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-10-28","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8370_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6845-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – This Act shall be known as the \"Children's Television Act of 1997\" ."}},{"id":"PH-H6845-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of policy. – The State recognizes the vital role of the youth in nation-building and shall promote and protect their physical, moral, spiritual, intellectual and social well-being by enhancing their over-all development, taking into account sectoral needs and conditions in the development of educational, cultural, recreational policies and programs addressed to them.\nLikewise, the State recognizes the importance and impact of broadcast media, particularly television programs on the value formation and intellectual development of children and must take steps to support and protect children's interests by providing television programs that reflect their needs, concerns and interests without exploiting them.\nThe State recognizes broadcasting as a form of mass communication guaranteed by the Constitution, the exercise of which is impressed with public interest, and which imposes upon the broadcast industry the social responsibility of ensuring that its activities serve the interest and welfare of the Filipino people."}},{"id":"PH-H6845-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of terms. – For purposes of this Act, the following terms shall mean:\na) Children – all persons below eighteen (18) years old;\nb) Children's television – refers to programs and other materials broadcast on television that are specifically designed for viewing by children;\nc) Child-friendly programs – refer to programs not specifically designed for viewing by children but which serve to further the positive development of children and contain no elements that may result in physical, mental and emotional harm to them. These include various formats and genre that appeal to children and are made available for all ages from early childhood to adolescence; and\nd) Child-viewing hours – hours which are considered to be appropriate for children to watch television taking into account other activities which are necessary or desirable for their balanced development."}},{"id":"PH-H6845-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Establishment of a National Council for Children's Television. – There is hereby established a National Council for Children's Television (NCCT), hereinafter referred to as the Council, which shall be attached to the Office of the President for purposes of administrative supervision.\nThe Council shall be composed of five (5) members who shall be appointed by the President for a term of three (3) years: Provided, That of the first appointees:\na) the term of the first set of two (2) members shall be for three (3) years;\nb) the term of the second set of two (2) members shall be for two (2) years; and\nc) the term of the remaining member shall be for one (1) year.\nThe members of the Council shall elect a chairperson from among themselves.\nMembers of the Council shall be appointed on the basis of their integrity, high degree of professionalism and having distinguished themselves as an authority in the promotion of children's rights to responsible television programming and shall represent the following sectors, namely: academe, broadcast media, child development specialists, parents and child-focused non-government organizations duly registered with the Securities and Exchange Commission (SEC) and with membership preferably in all the cities and provinces throughout the country. The nominees shall be nominated by their respective organization and the Council for the Welfare of Children in consultation with the Advisory Committee.\nThe members of the Council shall serve and continue to hold office until their successors shall have been appointed and qualified. Should a member of the Council fail to complete his/her term, the successor shall be appointed by the President, but only for the unexpired portion of the term.\nThe ranks, emoluments and allowances of the members of the Council shall be in accordance with the Salary Standardization Law and other applicable laws."}},{"id":"PH-H6845-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Council Secretariat. – The Council shall organize a secretariat to be headed by an Executive Director and with not more than twenty (20) personnel, as may be determined by the Council. The Council shall determine the secretariat's staffing pattern, determine the qualifications, duties, responsibilities and functions, as well as compensation for the positions to be created by the Council upon recommendation of the Executive Director subject to the National Compensation and Classification Plan and other existing Civil Service rules and regulations."}},{"id":"PH-H6845-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Advisory Committee and its composition. – There is hereby constituted an Advisory Committee which shall assist the Council in the formulation of national policies pertaining to children's broadcast programs and in monitoring its implementation. The Council and the Advisory Committee shall meet at least once every quarter of a year.\nThe members of the Advisory Committee shall be composed of the following:\na) the Executive Director of the Council for the Welfare of Children;\nb) the Chairman or Executive Director of the National Commission for Culture and the Arts;\nc) the President of the Kapisanan ng mga Brodkaster sa Pilipinas;\nd) the President or Executive Director of the Philippine Association of National Advertisers;\ne) Press Undersecretary/Officer-In-Charge of the Philippine Information Agency;\nf) the Chairman of the Movie and Television Review and Classification Board; and\ng) a representative from the National Telecommunications Commission.\nWhenever any member of the Advisory Committee is unable to attend, he or she shall designate a representative to attend as his or her alternate."}},{"id":"PH-H6845-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Functions of the Council. – The Council shall have the following functions:\na) to formulate and recommend plans, policies and priorities for government and private sector ( i.e. broadcasters, producers, advertisers) action towards the development of high quality locally-produced children's television programming, to meet the developmental and informational needs of children;\nb) to promote and encourage the production and broadcasting of developmentally- appropriate television programs for children through the administration of a national endowment fund for children's television and other necessary mechanisms;\nc) to monitor, review and classify children's television programs and advertisements aired during the hours known to be child-viewing hours in order to take appropriate action such as disseminating information to the public and bringing monitoring results to the attention of concerned agencies for appropriate action;\nd) to formulate, together with the television broadcast industry, a set of standards for television programs shown during child-viewing hours and work closely with the industry for the adoption and implementation of said standards;\ne) to initiate the conduct of research for policy formulation and program development and disseminate its results to broadcasters, advertisers, parents and educators on issues related to television and Filipino children;\nf) to promote media education within the formal school system and other non-formal means in cooperation with private organizations;\ng) to monitor the implementation of this Act and other existing government policies and regulations pertaining to children's broadcast programs, as well as to recommend and require the appropriate government agencies and/or self-regulatory bodies concerned to enforce the appropriate sanctions for violations of these regulations and policies based on their respective mandates;\nh) to recommend to Congress appropriate legislative measures which will grant incentives for independent producers and broadcasters to encourage the production of quality local children's television programs; and\n(i) to act on complaints committed in violation of this Act with the goal of protecting children from the negative and harmful influences and to cause or initiate the prosecution of violators of this Act."}},{"id":"PH-H6845-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Submission of comprehensive media program for children. – Within one (1) year from the effectivity of this Act, the Council in consultation with the Advisory Committee shall submit to Congress a comprehensive development and protection program with the end in view of formulating policies on children's media programs, and recommending plans and priorities for government towards the promotion, development, production and broadcasting of developmentally -appropriate media programs for children. Likewise, it shall prescribe an appropriate set of criteria for evaluating programs with the end in view of establishing a Television Violence Rating Code.\nTowards this end, the Council may consider internationally-accepted programs of action for children's television. More particularly, the Council shall be guided by the following standards herein to be known as \"The Charter of Children's Television\" :\na) Children should have programs of high quality which are made specifically for them, and which do not exploit them. These programs, in addition to being entertaining should allow children to develop physically, mentally and socially to their fullest potential;\nb) Children should hear, see and express themselves, their culture, languages and life experiences through television programs which affirm their sense of self, community and place;\nc) Children's programs should promote an awareness and appreciation of other cultures in parallel with the child's own cultural background;\nd) Children's program should be wide-ranging in genre and content, but should not include gratuitous scenes of violence and sex;\ne) Children's program should be aired in regular time slots when children are available to view and/or distributed through widely accessible media or technologies;\nf) Sufficient funds must be made available to make these programs conform to the highest possible standards; and\ng) Government, production, distribution and funding organizations should recognize both the importance and vulnerability of indigenous children's television and the steps to support and protect it."}},{"id":"PH-H6845-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Allotment of air time for educational children's programs. – A minimum of fifteen percent (15%) of the daily total air time of each broadcasting network shall be allotted for child-friendly shows within the regular programming of all networks granted franchises or as a condition for renewal of broadcast licenses hereinafter, to be included as part of the network's responsibility of serving the public."}},{"id":"PH-H6845-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Implementing rules and regulations. – The Council, in consultation with all appropriate government agencies and non-government organizations, shall issue the necessary rules and regulations for the implementation of this Act within ninety (90) days after its effectivity."}},{"id":"PH-H6845-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Penalty. – In the exercise of its administrative function, the Council shall petition the proper government agencies and/or appropriate self-regulatory bodies to suspend, revoke or cancel the license to operate television stations found violating any provision of this Act and its implementing rules and regulations."}},{"id":"PH-H6845-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The National Endowment Fund for Children's Television. – The creation of a National Endowment Fund for Children's Television, hereinafter referred to as the Fund, is created for the promotion of high standards of indigenous program development in children's television and media specifically intended for Filipino children. An amount of Thirty million pesos (P30,000,000) sourced from the income of the lotto operations of the Philippine Charity Sweepstakes Office (PCSO) and another Thirty million pesos (P30,000,000) from the gross income of the Philippine Gaming Corporation (PAGCOR) shall form part of the Fund.\na) The Fund shall be created for the purpose of developing and producing high quality television programs that are culturally-relevant and developmentally- appropriate for children.\nb) The Fund is intended to contribute to the development of media programs that contribute to Filipino children's awareness and appreciation for their cultural identity, national heritage and social issues that will in turn help them grow to be productive and nationalistic citizens.\nc) Access to the Fund shall be provided by the Council through a grant application process for qualified producers and organizations with proven track record in the production of high quality children's television programs. Necessary requirements are to be submitted to the Council for approval.\nd) Copyright for programs and products to be developed with assistance from the Fund will be jointly owned by the Council and the producers.\ne) Priority shall be given to independent producers and organizations or institutions including youth organizations who do not have access to the resources of a national network.\nf) The Council is authorized to accept grants, contributions or donations from private corporations and international donors for the National Endowment Fund for Children's Television: Provided , That such grants, contributions, or donations are exempted from donor's and donee's taxes: Provided, further, That these funds will be used strictly for the endowment fund."}},{"id":"PH-H6845-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Appropriations. – For the initial operating expenses of the Council, the amount of Five million pesos (P5,000,000) is hereby appropriated out of the funds of the National Treasury not otherwise appropriated. Thereafter, it shall submit to the Department of Budget and Management its proposed budget for inclusion in the General Appropriations Act, approved by Congress."}},{"id":"PH-H6845-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Separability clause. – If any provision of this Act is declared unconstitutional, the same shall not affect the validity and effectivity of the other provisions thereof."}},{"id":"PH-H6845-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealing clause. – All laws, decrees, executive orders, presidential proclamations, rules and regulations or parts thereof contrary to or inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6845-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity clause. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in at least two (2) newspapers of general circulation."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Children's Television Act of 1997","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6846"] = {"id":"PH-H6846","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8371_1997.html","fetchedAt":"2026-10-06","articleCount":84,"structureMode":"ARTICLE","title":{"zh":"1997 年原住民权利法","en":"The Indigenous Peoples Rights Act of 1997","orig":"The Indigenous Peoples Rights Act of 1997 An Act to Recognize, Protect and Promote the Rights of Indigenous Cultural Communities/Indigenous People, Creating a National Commission of Indigenous People, Establishing Implementing Mechanisms, Appropriating Funds Therefor, and for other purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8371","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-10-29","completenessNote":"全文，共 84 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8371_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6846-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. - This Act shall be known as \"The Indigenous Peoples Rights Act of 1997.\""}},{"id":"PH-H6846-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of State Policies. - The State shall recognize and promote all the rights of Indigenous Cultural Communities/Indigenous Peoples (ICCs/IPs) hereunder enumerated within the framework of the Constitution:\na) The State shall recognize and promote the rights of ICCs/IPs within the framework of national unity and development; b)The State shall protect the rights of ICCs/IPs to their ancestral domains to ensure their economic, social and cultural well being and shall recognize the applicability of customary laws governing property rights or relations in determining the ownership and extent of ancestral domain;\nc) The State shall recognize, respect and protect the rights of ICCs/IPs to preserve and develop their cultures, traditions and institutions. It shall consider these rights in the formulation of national laws and policies;\nd) The State shall guarantee that members of the ICCs/IPs regardless of sex, shall equally enjoy the full measure of human rights and freedoms without distinctions or discriminations;\ne) The State shall take measures, with the participation of the ICCs/IPs concerned, to protect their rights and guarantee respect for their cultural integrity, and to ensure that members of the ICCs/IPs benefit on an equal footing from the rights and opportunities which national laws and regulations grant to other members of the population and\nf) The State recognizes its obligations to respond to the strong expression of the ICCs/IPs for cultural integrity by assuring maximum ICC/IP participation in the direction of education, health, as well as other services of ICCs/IPs, in order to render such services more responsive to the needs and desires of these communities.\nTowards these ends, the State shall institute and establish the necessary mechanisms to enforce and guarantee the realization of these rights, taking into consideration their customs, traditions, values, beliefs, their rights to their ancestral domains.\nDEFINITION OF TERMS"}},{"id":"PH-H6846-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Definition of Terms. - For purposes of this Act, the following terms shall mean:\na) Ancestral Domains - Subject to Section 56 hereof, refer to all areas generally belonging to ICCs/IPs comprising lands,inland waters, coastal areas, and natural resources therein, held under a claim of ownership, occupied or possessed by ICCs/IPs, themselves or through their ancestors, communally or individually since time immemorial, continuously to the present except when interrupted by war, force majeure or displacement by force, deceit, stealth or as a consequence of government projects or any other voluntary dealings entered into by government and private individuals, corporations, and which are necessary to ensure their economic, social and cultural welfare. It shall include ancestral land, forests, pasture, residential, agricultural, and other lands individually owned whether alienable and disposable or otherwise, hunting grounds, burial grounds, worship areas, bodies of water, mineral and other natural resources, and lands which may no longer be exclusively occupied by ICCs/IPs but from which their traditionally had access to for their subsistence and traditional activities, particularly the home ranges of ICCs/IPs who are still nomadic and/or shifting cultivators;\nb) Ancestral Lands - Subject to Section 56 hereof, refers to land occupied, possessed and utilized by individuals, families and clans who are members of the ICCs/IPs since time immemorial, by themselves or through their predecessors-in-interest, under claims of individual or traditional group ownership,continuously, to the present except when interrupted by war, force majeure or displacement by force, deceit, stealth, or as a consequence of government projects and other voluntary dealings entered into by government and private individuals/corporations, including, but not limited to, residential lots, rice terraces or paddies, private forests, swidden farms and tree lots;\nc) Certificate of Ancestral Domain Title - refers to a title formally recognizing the rights of possession and ownership of ICCs/IPs over their ancestral domains identified and delineated in accordance with this law;\nd) Certificate of Ancestral Lands Title - refers to a title formally recognizing the rights of ICCs/IPs over their ancestral lands;\ne) Communal Claims - refer to claims on land, resources and rights thereon, belonging to the whole community within a defined territory\nf) Customary Laws - refer to a body of written and/or unwritten rules, usages, customs and practices traditionally and continually recognized, accepted and observed by respective ICCs/IPs;\ng) Free and Prior Informed Consent - as used in this Act shall mean the consensus of all members of the ICCs/IPs to; be determined in accordance with their respective customary laws and practices, free from any external manipulation, interference and coercion, and obtained after fully disclosing the intent and scope of the activity, in a language an process understandable to the community;\nh) Indigenous Cultural Communities/Indigenous Peoples - refer to a group of people or homogenous societies identified by self-ascription and ascription by other, who have continuously lived as organized community on communally bounded and defined territory, and who have, under claims of ownership since time immemorial, occupied, possessed customs, tradition and other distinctive cultural traits, or who have, through resistance to political, social and cultural inroads of colonization, non-indigenous religions and culture, became historically differentiated from the majority of Filipinos. ICCs/IPs shall likewise include peoples who are regarded as indigenous on account of their descent from the populations which inhabited the country, at the time of conquest or colonization, or at the time of inroads of non-indigenous religions and cultures, or the establishment of present state boundaries, who retain some or all of their own social, economic, cultural and political institutions, but who may have been displaced from their traditional domains or who may have resettled outside their ancestral domains;\n(i) Indigenous Political Structure - refer to organizational and cultural leadership systems, institutions, relationships, patterns and processed for decision-making and participation, identified by ICCs/IPs such as, but not limited to, Council of Elders, Council of Timuays, Bodong Holder, or any other tribunal or body of similar nature;\nj) Individual Claims - refer to claims on land and rights thereon which have been devolved to individuals, families and clans including, but not limited to, residential lots, rice terraces or paddies and tree lots;\nk) National Commission on Indigenous Peoples (NCIP) - refers to the office created under this Act, which shall be under the Office of the President, and which shall be the primary government agency responsible for the formulation and implementation of policies, plans and programs to recognize, protect and promote the rights of ICCs/IPs;\nl) Native Title - refers to pre-conquest rights to lands and domains which, as far back as memory reaches, have been held under a claim of private ownership by ICCs/IPs, have never been public lands and are thus indisputably presumed to have been held that way since before the Spanish Conquest;\nm) Nongovernment Organization - refers to a private, nonprofit voluntary organization that has been organized primarily for the delivery of various services to the ICCs/IPs and has an established track record for effectiveness and acceptability in the community where it serves;\nn) People's Organization - refers to a private, nonprofit voluntary organization of members of an ICC/IP which is accepted as representative of such ICCs/IPs;\no) Sustainable Traditional Resource Rights - refer to the rights of ICCs/IPs to sustainably use,manage, protect and conserve a) land, air, water, and minerals; b) plants, animals and other organisms; c) collecting, fishing and hunting grounds; d) sacred sites; and e) other areas of economic, ceremonial and aesthetic value in accordance with their indigenous knowledge, beliefs, systems and practices; and\np) Time Immemorial - refers to a period of time when as far back as memory can go, certain ICCs/IPs are known to have occupied, possessed in the concept of owner, and utilized a defined territory devolved to them, by operation of customary law or inherited from their ancestors, in accordance with their customs and traditions.\nRIGHTS TO ANCESTRAL DOMAINS"}},{"id":"PH-H6846-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Concept of Ancestral Lands/Domains. - Ancestral lands/domains shall include such concepts of territories which cover not only the physical environment but the total environment including the spiritual and cultural bonds to the area which the ICCs/IPs possess, occupy and use and to which they have claims of ownership."}},{"id":"PH-H6846-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Indigenous Concept of Ownership. - Indigenous concept of ownership sustains the view that ancestral domains and all resources found therein shall serve as the material bases of their cultural integrity. The indigenous concept of ownership generally holds that ancestral domains are the ICC's/IP's private but community property which belongs to all generations and therefore cannot be sold, disposed or destroyed. It likewise covers sustainable traditional resource rights."}},{"id":"PH-H6846-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Composition of Ancestral Lands/Domains. - Ancestral lands and domains shall consist of all areas generally belonging to ICCs/IPs as referred under Sec. 3, items (a) and (b) of this Act."}},{"id":"PH-H6846-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Rights to Ancestral Domains. - The rights of ownership and possession of ICCs/IPs t their ancestral domains shall be recognized and protected. Such rights shall include:\na. Rights of Ownership.- The right to claim ownership over lands, bodies of water traditionally and actually occupied by ICCs/IPs, sacred places, traditional hunting and fishing grounds, and all improvements made by them at any time within the domains;\nb. Right to Develop Lands and Natural Resources. - Subject to Section 56 hereof, right to develop, control and use lands and territories traditionally occupied, owned, or used; to manage and conserve natural resources within the territories and uphold the responsibilities for future generations; to benefit and share the profits from allocation and utilization of the natural resources found therein; the right to negotiate the terms and conditions for the exploration of natural resources in the areas for the purpose of ensuring ecological, environmental protection and the conservation measures, pursuant to national and customary laws; the right to an informed and intelligent participation in the formulation and implementation of any project, government or private, that will affect or impact upon the ancestral domains and to receive just and fair compensation for any damages which they sustain as a result of the project; and the right to effective measures by the government to prevent any interfere with, alienation and encroachment upon these rights;\nc. Right to Stay in the Territories - The right to stay in the territory and not be removed therefrom. No ICCs/IPs will be relocated without their free and prior informed consent, nor through any means other than eminent domain. Where relocation is considered necessary as an exceptional measure, such relocation shall take place only with the free and prior informed consent of the ICCs/IPs concerned and whenever possible, they shall be guaranteed the right to return to their ancestral domains, as soon as the grounds for relocation cease to exist. When such return is not possible, as determined by agreement or through appropriate procedures, ICCs/IPs shall be provided in all possible cases with lands of quality and legal status at least equal to that of the land previously occupied by them, suitable to provide for their present needs and future development. Persons thus relocated shall likewise be fully compensated for any resulting loss or injury;\nd. Right in Case of Displacement. - In case displacement occurs as a result of natural catastrophes, the State shall endeavor to resettle the displaced ICCs/IPs in suitable areas where they can have temporary life support system: Provided, That the displaced ICCs/IPs shall have the right to return to their abandoned lands until such time that the normalcy and safety of such lands shall be determined: Provided, further, That should their ancestral domain cease to exist and normalcy and safety of the previous settlements are not possible, displaced ICCs/IPs shall enjoy security of tenure over lands to which they have been resettled: Provided, furthermore, That basic services and livelihood shall be provided to them to ensure that their needs are adequately addressed:\ne. Right to Regulate Entry of Migrants. - Right to regulate the entry of migrant settlers and organizations into the domains;\nf. Right to Safe and Clean Air and Water. - For this purpose, the ICCs/IPs shall have access to integrated systems for the management of their inland waters and air space;\ng. Right to Claim Parts of Reservations. - The right to claim parts of the ancestral domains which have been reserved for various purposes, except those reserved and intended for common and public welfare and service; and\nh. Right to Resolve Conflict. - Right to resolve land conflicts in accordance with customary laws of the area where the land is located, and only in default thereof shall the complaints be submitted to amicable settlement and to the Courts of Justice whenever necessary."}},{"id":"PH-H6846-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Rights to Ancestral Lands. - The right of ownership and possession of the ICCs/IPs, to their ancestral lands shall be recognized and protected.\na. Right to transfer land/property. - Such right shall include the right to transfer land or property rights to/among members of the same ICCs/IPs, subject to customary laws and traditions of the community concerned.\nb. Right to Redemption. - In cases where it is shown that the transfer of land/property rights by virtue of any agreement or devise, to a non-member of the concerned ICCs/IPs is tainted by the vitiated consent of the ICCs/IPs,or is transferred for an unconscionable consideration or price, the transferor ICC/IP shall have the right to redeem the same within a period not exceeding fifteen (15) years from the date of transfer."}},{"id":"PH-H6846-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Responsibilities of ICCs/IPs to their Ancestral Domains. - ICCs/IPs occupying a duly certified ancestral domain shall have the following responsibilities:\na. Maintain Ecological Balance- To preserve, restore, and maintain a balanced ecology in the ancestral domain by protecting the flora and fauna, watershed areas, and other reserves;\nb. Restore Denuded Areas- To actively initiate, undertake and participate in the reforestation of denuded areas and other development programs and projects subject to just and reasonable remuneration; and\nc. Observe Laws- To observe and comply with the provisions of this Act and the rules and regulations for its effective implementation."}},{"id":"PH-H6846-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Unauthorized and Unlawful Intrusion. - Unauthorized and unlawful intrusion upon, or use of any portion of the ancestral domain, or any violation of the rights herein before enumerated, shall be punishable under this law. Furthermore, the Government shall take measures to prevent non-ICCs/IPs from taking advantage of the ICCs/IPs customs or lack of understanding of laws to secure ownership, possession of land belonging to said ICCs/IPs."}},{"id":"PH-H6846-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Recognition of Ancestral Domain Rights. - The rights of ICCs/IPs to their ancestral domains by virtue of Native Title shall be recognized and respected. Formal recognition, when solicited by ICCs/IPs concerned, shall be embodied in a Certificate of Ancestral Domain Title (CADT), which shall recognize the title of the concerned ICCs/IPs over the territories identified and delineated."}},{"id":"PH-H6846-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Option to Secure Certificate of Title under Commonwealth Act 141, as amended, or the Land Registration Act 496. - Individual members of cultural communities, with respect to individually-owned ancestral lands who, by themselves or through their predecessors-in -interest, have been in continuous possession and occupation of the same in the concept of owner since the immemorial or for a period of not less than thirty (30) years immediately preceding the approval of this Act and uncontested by the members of the same ICCs/IPs shall have the option to secure title to their ancestral lands under the provisions of Commonwealth Act 141, as amended, or the Land Registration Act 496.\nFor this purpose, said individually-owned ancestral lands, which are agricultural in character and actually used for agricultural, residential, pasture, and tree farming purposes, including those with a slope of eighteen percent (18%) or more, are hereby classified as alienable and disposable agricultural lands.\nThe option granted under this Section shall be exercised within twenty (20) years from the approval of this Act.\nRIGHT TO SELF-GOVERNANCE AND EMPOWERMENT"}},{"id":"PH-H6846-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Self-Governance. - The State recognizes the inherent right of ICCs/IPs to self-governance and self-determination and respects the integrity of their values, practices and institutions. Consequently, the State shall guarantee the right of ICCs/IPs to freely pursue their economic, social and cultural development."}},{"id":"PH-H6846-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Support for Autonomous Regions. - The State shall continue to strengthen and support the autonomous regions created under the Constitution as they may require or need. The State shall likewise encourage other ICCs/IPs not included or outside Muslim Mindanao and the Cordillera to use the form and content of their ways of life as may be compatible with the fundamental rights defined in the Constitution of the Republic of the Philippines and other internationally recognized human rights."}},{"id":"PH-H6846-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Justice System, Conflict Resolution Institutions and Peace Building Processes. - The ICCs/IPs shall have the right to use their own commonly accepted justice systems, conflict resolution institutions, peace building processes or mechanisms and other customary laws and practices within their respective communities and as may be compatible with the national legal system and with internationally recognized human rights."}},{"id":"PH-H6846-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Right to Participate in Decision -Making. - ICCs/IPs have the right to participate fully, if they so choose, at all levels of decision-making in matters which may affect their rights, lives and destinies through procedures determined by them as well as to maintain and develop their own indigenous political structures. Consequently, the State shall ensure that the ICCs/IPs shall be given mandatory representation in policy-making bodies and other local legislative councils."}},{"id":"PH-H6846-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Right to Determine and Decide Priorities for Development. - The ICCs/IPs shall have the right to determine and decide their own priorities for development affecting their lives, beliefs, institutions, spiritual well-being, and the lands they own, occupy or use. They shall participate in the formulation,implementation and evaluation of policies, plans and programs for national, regional and local development which may directly affect them."}},{"id":"PH-H6846-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Tribal Barangays. - The ICCs/IPs living in contiguous areas or communities where they form the predominant population but which are located in municipalities, provinces or cities where they do not constitute the majority of the population, may form or constitute a separate barangay in accordance with the Local Government Code on the creation of tribal barangays."}},{"id":"PH-H6846-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Role of Peoples Organizations. - The State shall recognize and respect the role of independent ICCs/IPs organizations to enable the ICCs/IPs to pursue and protect their legitimate and collective interests and aspirations through peaceful and lawful means."}},{"id":"PH-H6846-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Means for Development /Empowerment of ICCs/IPs. - The Government shall establish the means for the full development/empowerment of the ICCs/IPs own institutions and initiatives and, where necessary, provide the resources needed therefor.\nSOCIAL JUSTICE AND HUMAN RIGHTS"}},{"id":"PH-H6846-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Equal Protection and Non-discrimination of ICCs/IPs. - Consistent with the equal protection clause of the Constitution of the Republic of the Philippines, the Charter of the United Nations, the Universal Declaration of Human Rights including the Convention on the Elimination of Discrimination Against Women and International Human Rights Law, the State shall, with due recognition of their distinct characteristics and identity, accord to the members of the ICCs/IPs the rights, protections and privileges enjoyed by the rest of the citizenry. It shall extend to them the same employment rights, opportunities, basic services, educational and other rights and privileges available to every member of the society. Accordingly, the State shall likewise ensure that the employment of any form of force of coersion against ICCs/IPs shall be dealt with by law.\nThe State shall ensure that the fundamental human rights and freedoms as enshrined in the Constitution and relevant international instruments are guaranteed also to indigenous women. Towards this end, no provision in this Act shall be interpreted so as to result in the diminution of rights and privileges already recognized and accorded to women under existing laws of general application."}},{"id":"PH-H6846-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Rights during Armed Conflict. - ICCs/IPs have the right to special protection and security in periods of armed conflict. The State shall observe international standards, in particular, the Fourth Geneva Convention of 1949, for the protection of civilian populations in circumstances of emergency and armed conflict, and shall not recruit members of the ICCs/IPs against their will into armed forces, and in particular, for the use against other ICCs/IPs; not recruit children of ICCs/IPs into the armed forces under any circumstance; nor force indigenous individuals to abandon their lands, territories and means of subsistence, or relocate them in special centers for military purposes under any discriminatory condition."}},{"id":"PH-H6846-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Freedom from Discrimination and Right to Equal Opportunity and Treatment. - It shall be the right of the ICCs/IPs to be free from any form of discrimination, with respect to recruitment and conditions of employment, such that they may enjoy equal opportunities as other occupationally-related benefits, informed of their rights under existing labor legislation and of means available to them for redress, not subject to any coercive recruitment systems, including bonded labor and other forms of debt servitude; and equal treatment in employment for men and women, including the protection from sexual harassment.\nTowards this end, the State shall within the framework of national laws and regulations, and in cooperation with the ICCs/IPs concerned, adopt special measures to ensure the effective protection with regard to the recruitment and conditions of employment of persons belonging to these communities, to the extent that they are not effectively protected by the laws applicable to workers in general.\nICCs/IPs shall have the right to association and freedom for all trade union activities and the right to conclude collective bargaining agreements with employers' conditions. They shall likewise have the right not to be subject to working conditions hazardous to their health, particularly through exposure to pesticides and other toxic substances."}},{"id":"PH-H6846-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Unlawful Acts Pertaining to Employment. - It shall be unlawful for any person:\na. To discriminate against any ICC/IP with respect to the terms and conditions of employment on account of their descent. Equal remuneration shall be paid to ICC/IP and non-ICC/IP for work of equal value; and\nb. To deny any ICC/IP employee any right or benefit herein provided for or to discharge them for the purpose of preventing them from enjoying any of the rights or benefits provided under this Act."}},{"id":"PH-H6846-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Basic Services. - The ICC/IP have the right to special measures for the immediate, effective and continuing improvement of their economic and social conditions, including in the areas of employment, vocational training and retraining, housing, sanitation, health and social security. Particular attention shall be paid to the rights and special needs of indigenous women, elderly, youth, children and differently-abled persons. Accordingly, the State shall guarantee the right of ICCs/IPs to government 's basic services which shall include, but not limited to water and electrical facilities, education, health and infrastructure."}},{"id":"PH-H6846-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Women. - ICC/IP women shall enjoy equal rights and opportunities with men, as regards the social, economic, political and cultural spheres of life. The participation of indigenous women in the decision-making process in all levels, as well as in the development of society, shall be given due respect and recognition.\nThe State shall provide full access to education, maternal and child care, health and nutrition, and housing services to indigenous women. Vocational, technical, professional and other forms of training shall be provided to enable these women to fully participate in all aspects of social life. As far as possible, the State shall ensure that indigenous women have access to all services in their own languages."}},{"id":"PH-H6846-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Children and Youth. - The State shall recognize the vital role of the children and youth of ICCs/IPs in nation-building and shall promote and protect their physical, moral, spiritual, moral, spiritual, intellectual and social well-being. Towards this end, the State shall support all government programs intended for the development and rearing of the children and youth of ICCs/IPs for civic efficiency and establish such mechanisms as may be necessary for the protection of the rights of the indigenous children and youth."}},{"id":"PH-H6846-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Integrated System of Education. - The State shall, through the NCIP, provide a complete, adequate and integrated system of education, relevant to the needs of the children and Young people of ICCs/IPs.\nCULTURAL INTEGRITY"}},{"id":"PH-H6846-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Protection of Indigenous Culture, traditions and institutions. - The state shall respect, recognize and protect the right of the ICCs/IPs to preserve and protect their culture, traditions and institutions. It shall consider these rights in the formulation of national plans and policies."}},{"id":"PH-H6846-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Educational Systems. - The State shall provide equal access to various cultural opportunities to the ICCs/IPs through the educational system, public or cultural entities, scholarships, grants and other incentives without prejudice to their right to establish and control their educational systems and institutions by providing education in their own language, in a manner appropriate to their cultural methods of teaching and learning. Indigenous children/youth shall have the right to all levels and forms of education of the State."}},{"id":"PH-H6846-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Recognition of Cultural Diversity. - The State shall endeavor to have the dignity and diversity of the cultures, traditions, histories and aspirations of the ICCs/IPs appropriately reflected in all forms of education, public information and cultural-educational exchange. Consequently, the State shall take effective measures, in consultation with ICCs/IPs concerned, to eliminate prejudice and discrimination and to promote tolerance, understanding and good relations among ICCs/IPs and all segments of society. Furthermore, the Government shall take effective measures to ensure that State-owned media duly reflect indigenous cultural diversity. The State shall likewise ensure the participation of appropriate indigenous leaders in schools, communities and international cooperative undertakings like festivals, conferences, seminars and workshops to promote and enhance their distinctive heritage and values."}},{"id":"PH-H6846-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Community Intellectual Rights. - ICCs/IPs have the right to practice and revitalize their own cultural traditions and customs. The State shall preserve, protect and develop the past, present and future manifestations of their cultures as well as the right to the restitution of cultural, intellectual, religious, and spiritual property taken without their free and prior informed consent or in violation of their laws, traditions and customs."}},{"id":"PH-H6846-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Rights to Religious, Cultural Sites and Ceremonies. - ICCs/IPs shall have the right to manifest, practice, develop teach their spiritual and religious traditions, customs and ceremonies; the right to maintain, protect and have access to their religious and cultural sites; the right to use and control of ceremonial object; and the right to the repatriation of human remains. Accordingly, the State shall take effective measures, in cooperation with the burial sites, be preserved, respected and protected. To achieve this purpose, it shall be unlawful to:\na. Explore, excavate or make diggings on archeological sites of the ICCs/IPs for the purpose of obtaining materials of cultural values without the free and prior informed consent of the community concerned; and\nb. Deface, remove or otherwise destroy artifacts which are of great importance to the ICCs/IPs for the preservation of their cultural heritage."}},{"id":"PH-H6846-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Right to Indigenous Knowledge Systems and Practices and to Develop own Sciences and Technologies. - ICCs/IPs are entitled to the recognition of the full ownership and control and protection of their cultural and intellectual rights. They shall have the right to special measures to control, develop and protect their sciences, technologies and cultural manifestations, including human and other genetic resources, seeds, including derivatives of these resources, traditional medicines and health practices, vital medicinal plants, animals and minerals, indigenous knowledge systems and practices, knowledge of the properties of fauna and flora, oral traditions, literature, designs, and visual and performing arts."}},{"id":"PH-H6846-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Access to Biological and Genetic Resources. - Access to biological and genetic resources and to indigenous knowledge related to the conservation, utilization and enhancement of these resources, shall be allowed within ancestral lands and domains of the ICCs/IPs only with a free and prior informed consent of such communities, obtained in accordance with customary laws of the concerned community."}},{"id":"PH-H6846-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Sustainable Agro-Technical Development. - The State shall recognize the right of ICCs/IPs to a sustainable agro-technological development and shall formulate and implement programs of action for its effective implementation. The State shall likewise promote the bio-genetic and resource management systems among the ICCs/IPs and shall encourage cooperation among government agencies to ensure the successful sustainable development of ICCs/IPs."}},{"id":"PH-H6846-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Funds for Archeological and Historical Sites. - The ICCs/IPs shall have the right to receive from the national government all funds especially earmarked or allocated for the management and preservation of their archeological and historical sites and artifacts with the financial and technical support of the national government agencies.\nNATIONAL COMMISSION ON INDIGENOUS PEOPLES (NCIP)"}},{"id":"PH-H6846-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"National Commission on Indigenous Cultural Communities /Indigenous Peoples (NCCP). - to carry out the policies herein set forth, there shall be created the National Commission on ICCs/IPs (NCIP), which shall be the primary government agency responsible for the formulation and implementation of policies, plans and programs to promote and protect the rights and well-being of the ICCs/IPs and the recognition of their ancestral domains as well as their rights thereto."}},{"id":"PH-H6846-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Mandate. - The NCIP shall protect and promote the interest and well-being of the ICCs/IPs with due regard to their beliefs, customs, traditions and institutions."}},{"id":"PH-H6846-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Composition. - The NCIP shall be an independent agency under the Office of the President and shall be composed of seven (7) Commissioners belonging to ICCs/IPs, one (1) of whom shall be the Chairperson. The Commissioners shall be appointed by the President of the Philippines from a list of recommendees submitted by authentic ICCs/IPs: Provided, That the seven (7) Commissioners shall be appointed specifically from each of the following ethnographic areas: Region I and the Cordilleras; Region II; the rest of Luzon; Island Groups including Mindoro, Palawan, Romblon, Panay and the rest of the Visayas; Northern and Western Mindanao; Southern and Eastern Mindanao; and Central Mindanao: Provided, That at least two (2) of the seven (7) Commissioners shall be women."}},{"id":"PH-H6846-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Qualifications, Tenure, Compensation. - The Chairperson and the six (6) Commissioners must be natural born Filipino citizens, bonafide members of ICCs/IPs as certified by his/her tribe, experienced in ethnic affairs and who have worked for at least ten (10) years with an ICC/IP community and/or any government agency involved in ICC/IP, at least 35 years of age at the time of appointment, and must be of proven honesty and integrity: Provided, That at least two (2) of the seven (7) Commissioners shall be the members of the Philippine Bar: Provided, further, That the members of the NCIP shall hold office for a period of three (3) years, and may be subject to re-appointment for another term: Provided, furthermore, That no person shall serve for more than two (2) terms. Appointment to any vacancy shall only be for the unexpired term of the predecessor and in no case shall a member be appointed or designated in a temporary or acting capacity: Provided, finally, That the Chairperson and the Commissioners shall be entitled to compensation in accordance with the Salary Standardization Law."}},{"id":"PH-H6846-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Removal from Office. - Any member of the NCIP may be removed from office by the President, on his own initiative or upon recommendation by any indigenous community, before the expiration of his term for cause and after complying with due process requirement of law."}},{"id":"PH-H6846-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Appointment of Commissioners. - The President shall appoint the seven (7) Commissioners of the NCIP within ninety (90) days from the effectivity of this Act."}},{"id":"PH-H6846-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Powers and Functions. - To accomplish its mandate, the NCIP shall have the following powers, jurisdiction and function:\na) To serve as the primary government agency through which ICCs/IPs can seek government assistance and as the medium, thorough which such assistance may be extended;\nb) To review and assess the conditions of ICCs/IPs including existing laws and policies pertinent thereto and to propose relevant laws and policies to address their role in national development;\nc) To formulate and implement policies, plans, programs and projects for the economic, social and cultural development of the ICCs/IPs and to monitor the implementation thereof;\nd) To request and engage the services and support of experts from other agencies of government or employ private experts and consultants as may be required in the pursuit of its objectives;\ne) To issue certificate of ancestral land/domain title;\nf) Subject to existing laws, to enter into contracts, agreements, or arrangement, with government or private agencies or entities as may be necessary to attain the objectives of this Act, and subject to the approval of the President, to obtain loans from government lending institutions and other lending institutions to finance its programs;\ng) To negotiate for funds and to accept grants, donations, gifts and/or properties in whatever form and from whatever source, local and international, subject to the approval of the President of the Philippines, for the benefit of ICCs/IPs and administer the same in accordance with the terms thereof; or in the absence of any condition, in such manner consistent with the interest of ICCs/IPs as well as existing laws;\nh) To coordinate development programs and projects for the advancement of the ICCs/IPs and to oversee the proper implementation thereof;\n(i) To convene periodic conventions or assemblies of IPs to review, assess as well as propose policies or plans;\nj) To advise the President of the Philippines on all matters relating to the ICCs/IPs and to submit within sixty (60) days after the close of each calendar year, a report of its operations and achievements;\nk) To submit to Congress appropriate legislative proposals intended to carry out the policies under this Act;\nl) To prepare and submit the appropriate budget to the Office of the President;\nm) To issue appropriate certification as a pre-condition to the grant of permit, lease, grant, or any other similar authority for the disposition, utilization, management and appropriation by any private individual, corporate entity or any government agency, corporation or subdivision thereof on any part or portion of the ancestral domain taking into consideration the consensus approval of the ICCs/IPs concerned;\nn) To decide all appeals from the decisions and acts of all the various offices within the Commission:\no) To promulgate the necessary rules and regulations for the implementation of this Act;\np) To exercise such other powers and functions as may be directed by the President of the Republic of the Philippines; and\nq) To represent the Philippine ICCs/IPs in all international conferences and conventions dealing with indigenous peoples and other related concerns."}},{"id":"PH-H6846-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Accessibility and Transparency. - Subject to such limitations as may be provided by law or by rules and regulations promulgated pursuant thereto, all official records, documents and papers pertaining to official acts, transactions or decisions, as well as research data used as basis for policy development of the Commission shall be made accessible to the public."}},{"id":"PH-H6846-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Officers within the NCIP. - The NCIP shall have the following offices which shall be responsible for the implementation of the policies herein after provided:\na. Ancestral Domains Office - The Ancestral Domain Office shall be responsible for the identification, delineation and recognition of ancestral land/domains. It shall also be responsible for the management of ancestral lands/domains in accordance with the master plans as well as the implementation of the ancestral domain rights of the ICCs/IPs as provided in Chapter III of this Act. It shall also issue, upon the free and prior informed consent of the ICCs/IPs concerned, certification prior to the grant of any license, lease or permit for the exploitation of natural resources affecting the interests of ICCs/IPs in protecting the territorial integrity of all ancestral domains. It shall likewise perform such other functions as the Commission may deem appropriate and necessary;\nb. Office on Policy, Planning and Research - The Office on Policy, Planning and Research shall be responsible for the formulation of appropriate policies and programs for ICCs/IPs such as, but not limited to, the development of a Five-Year Master Plan for the ICCs/IPs. Such plan shall undergo a process such that every five years, the Commission shall endeavor to assess the plan and make ramifications in accordance with the changing situations. The Office shall also undertake the documentation of customary law and shall establish and maintain a Research Center that would serve as a depository of ethnographic information for monitoring, evaluation and policy formulation. It shall assist the legislative branch of the national government in the formulation of appropriate legislation benefiting ICCs/IPs.\nc. Office of Education, Culture and Health - The Office on Culture, Education and Health shall be responsible for the effective implementation of the education, cultural and related rights as provided in this Act. It shall assist, promote and support community schools, both formal and non-formal, for the benefit of the local indigenous community, especially in areas where existing educational facilities are not accessible to members of the indigenous group. It shall administer all scholarship programs and other educational rights intended for ICC/IP beneficiaries in coordination with the Department of Education, Culture and Sports and the Commission on Higher Education. It shall undertake, within the limits of available appropriation, a special program which includes language and vocational training, public health and family assistance program and related subjects.\nIt shall also identify ICCs/IPs with potential training in the health profession and encourage and assist them to enroll in schools of medicine, nursing, physical therapy and other allied courses pertaining to the health profession.\nTowards this end, the NCIP shall deploy a representative in each of the said offices who shall personally perform the foregoing task and who shall receive complaints from the ICCs/IPs and compel action from appropriate agency. It shall also monitor the activities of the National Museum and other similar government agencies generally intended to manage and preserve historical and archeological artifacts of the ICCs /IPs and shall be responsible for the implementation of such other functions as the NCIP may deem appropriate and necessary;\nd. Office on Socio-Economic Services and Special Concerns - The Office on Socio-Economic Services and Special Concerns shall serve as the Office through which the NCIP shall coordinate with pertinent government agencies specially charged with the implementation of various basic socio-economic services, policies, plans and programs affecting the ICCs/IPs to ensure that the same are properly and directly enjoyed by them. It shall also be responsible for such other functions as the NCIP may deem appropriate and necessary;\ne. Office of Empowerment and Human Rights - The Office of Empowerment and Human Rights shall ensure that indigenous socio- political, cultural and economic rights are respected and recognized. It shall ensure that capacity building mechanisms are instituted and ICCs/IPs are afforded every opportunity, if they so choose, to participate in all level decision-making. It shall likewise ensure that the basic human rights, and such other rights as the NCIP may determine, subject to existing laws, rules and regulations are protected and promoted;\nf. Administrative Office - The Administrative Office shall provide the NCIP with economical, efficient and effective services pertaining to personnel, finance, records, equipment, security, supplies, and related services. It shall also administer the Ancestral Domains Fund; and\ng. Legal Affairs Office - There shall be a Legal Affairs Office which shall advice the NCIP on all legal matters concerning ICCs/IPs and which shall be responsible for providing ICCs/IPs with legal assistance in litigation involving community interest. It shall conduct preliminary investigation on the basis of complaints filed by the ICCs/IPs against a natural or juridical person believed to have violated ICCs/IPs rights. On the basis of its findings, it shall initiate the filing of appropriate legal or administrative action to the NCIP."}},{"id":"PH-H6846-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Other Offices. - The NCIP shall have the power to create additional offices as it may deem necessary subject to existing rules and regulations."}},{"id":"PH-H6846-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Regional and Field Offices. - Existing regional and field offices shall remain to function under the strengthened organizational structure of the NCIP. Other field office shall be created wherever appropriate and the staffing pattern thereof shall be determined by the NCIP: Provided, That in provinces where there are ICCs/IPs but without field offices, the NCIP shall establish field offices in said provinces."}},{"id":"PH-H6846-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Office of the Executive Director. - The NCIP shall create the Office of the Executive Director which shall serve as its secretariat. The office shall be headed by an Executive Director who shall be appointed by the President of the Republic of the Philippines upon the recommendation of the NCIP on a permanent basis. The staffing pattern of the office shall be determined by the NCIP subject to existing rules and regulations."}},{"id":"PH-H6846-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Consultative Body. - A body consisting of the traditional leaders, elders and representatives from the women and youth sectors of the different ICCs/IPs shall be constituted by the NCIP from the time to time to advise it on matters relating to the problems, aspirations and interests of the ICCs/IPs.\nDELINEATION AND RECOGNITION OF ANCESTRAL DOMAINS"}},{"id":"PH-H6846-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Delineation and Recognition of Ancestral Domains. - Self-delineation shall be guiding principle in the identification and delineation of ancestral domains. As such, the ICCs/IPs concerned shall have a decisive role in all the activities pertinent thereto. The Sworn Statement of the Elders as to the Scope of the territories and agreements/pacts made with neighboring ICCs/IPs, if any, will be essential to the determination of these traditional territories. The Government shall take the necessary steps to identify lands which the ICCs/IPs concerned traditionally occupy and guarantee effective protection of their rights of ownership and possession thereto. Measures shall be taken in appropriate cases to safeguard the rights of the ICCs/IPs concerned to land which may no longer be exclusively occupied by them, but to which they have traditionally had access for their subsistence and traditional activities, particularly of ICCs/IPs who are still nomadic and/or shifting cultivators."}},{"id":"PH-H6846-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Delineation Process. - The identification and delineation of ancestral domains shall be done in accordance with the following procedures:\na. Ancestral Domains Delineated Prior to this Act - The provisions hereunder shall not apply to ancestral domains/lands already delineated according to DENR Administrative Order No. 2, series of 1993, nor to ancestral lands and domains delineated under any other community/ancestral domain program prior to the enactment of his law. ICCs/IPs enactment of this law shall have the right to apply for the issuance of a Certificate of Ancestral Domain Title (CADT) over the area without going through the process outlined hereunder;\nb. Petition for Delineation - The process of delineating a specific perimeter may be initiated by the NCIP with the consent of the ICC/IP concerned, or through a Petition for Delineation filed with the NCIP, by a majority of the members of the ICCs/IPs;\nc. Delineation Paper - The official delineation of ancestral domain boundaries including census of all community members therein, shall be immediately undertaken by the Ancestral Domains Office upon filing of the application by the ICCs/IPs concerned. Delineation will be done in coordination with the community concerned and shall at all times include genuine involvement and participation by the members of the communities concerned;\nd. Proof required - Proof of Ancestral Domain Claims shall include the testimony of elders or community under oath, and other documents directly or indirectly attesting to the possession or occupation of the area since time immemorial by such ICCs/IPs in the concept of owners which shall be any one (1) of the following authentic documents:\n1. Written accounts of the ICCs/IPs customs and traditions;\n2. Written accounts of the ICCs/IPs political structure and institution;\n3. Pictures showing long term occupation such as those of old improvements, burial grounds, sacred places and old villages;\n4. Historical accounts, including pacts and agreements concerning boundaries entered into by the ICCs/IPs concerned with other ICCs/IPs;\n5. Survey plans and sketch maps;\n6. Anthropological data;\n7. Genealogical surveys;\n8. Pictures and descriptive histories of traditional communal forests and hunting grounds;\n9. Pictures and descriptive histories of traditional landmarks such as mountains, rivers, creeks, ridges, hills, terraces and the like; and\n10. Write-ups of names and places derived from the native dialect of the community.\ne. Preparation of Maps - On the basis of such investigation and the findings of fact based thereon, the Ancestral Domains Office of the NCIP shall prepare a perimeter map, complete with technical descriptions, and a description of the natural features and landmarks embraced therein;\nf. Report of Investigation and Other Documents - A complete copy of the preliminary census and a report of investigation, shall be prepared by the Ancestral Domains Office of the NCIP;\ng. Notice and Publication - A copy of each document, including a translation in the native language of the ICCs/IPs concerned shall be posted in a prominent place therein for at least fifteen (15) days. A copy of the document shall also be posted at the local, provincial and regional offices of the NCIP, and shall be published in a newspaper of general circulation once a week for two (2) consecutive weeks to allow other claimants to file opposition thereto within fifteen (15) days from the date of such publication: Provided, That in areas where no such newspaper exists, broadcasting in a radio station will be a valid substitute: Provided, further, That mere posting shall be deemed sufficient if both newspaper and radio station are not available;\nh. Endorsement to NCIP - Within fifteen (15) days from publication, and of the inspection process, the Ancestral Domains Office shall prepare a report to the NCIP endorsing a favorable action upon a claim that is deemed to have sufficient proof. However, if the proof is deemed insufficient, the Ancestral Domains Office shall require the submission of additional evidence: Provided, That the Ancestral Domains Office shall reject any claim that is deemed patently false or fraudulent after inspection and verification: Provided, further, That in case of rejection, the Ancestral Domains Office shall give the applicant due notice, copy furnished all concerned, containing the grounds for denial. The denial shall be appealable to the NCIP: Provided, furthermore, That in cases where there are conflicting claims, the Ancestral Domains Office shall cause the contending parties to meet and assist them in coming up with a preliminary resolution of the conflict, without prejudice to its full adjudication according to the selection below.\ni. Turnover of Areas Within Ancestral Domains Managed by Other Government Agencies - The Chairperson of the NCIP shall certify that the area covered is an ancestral domain. The secretaries of the Department of Agrarian Reform, Department of Environment and Natural Resources, Department of the Interior and Local Government, and Department of Justice, the Commissioner of the National Development Corporation, and any other government agency claiming jurisdiction over the area shall be notified thereof. Such notification shall terminate any legal basis for the jurisdiction previously claimed;\nj. Issuance of CADT - ICCs/IPs whose ancestral domains have been officially delineated and determined by the NCIP shall be issued a CADT in the name of the community concerned, containing a list of all those identified in the census; and\nk. Registration of CADTs - The NCIP shall register issued certificates of ancestral domain titles and certificates of ancestral lands titles before the Register of Deeds in the place where the property is situated."}},{"id":"PH-H6846-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Identification, Delineation and Certification of Ancestral Lands. -\na. The allocation of lands within any ancestral domain to individual or indigenous corporate (family or clan) claimants shall be left to the ICCs/IPs concerned to decide in accordance with customs and traditions;\nb. Individual and indigenous corporate claimants of ancestral lands which are not within ancestral domains, may have their claims officially established by filing applications for the identification and delineation of their claims with the Ancestral Domains Office. An individual or recognized head of a family or clan may file such application in his behalf or in behalf of his family or clan, respectively;\nc. Proofs of such claims shall accompany the application form which shall include the testimony under oath of elders of the community and other documents directly or indirectly attesting to the possession or occupation of the areas since time immemorial by the individual or corporate claimants in the concept of owners which shall be any of the authentic documents enumerated under Sec. 52 (d) of this act, including tax declarations and proofs of payment of taxes;\nd. The Ancestral Domains Office may require from each ancestral claimant the submission of such other documents, Sworn Statements and the like, which in its opinion, may shed light on the veracity of the contents of the application/claim;\ne. Upon receipt of the applications for delineation and recognition of ancestral land claims, the Ancestral Domains Office shall cause the publication of the application and a copy of each document submitted including a translation in the native language of the ICCs/IPs concerned in a prominent place therein for at least fifteen (15) days. A copy of the document shall also be posted at the local, provincial, and regional offices of the NCIP and shall be published in a newspaper of general circulation once a week for two (2) consecutive weeks to allow other claimants to file opposition thereto within fifteen (15) days from the date of such publication: Provided, That in areas where no such newspaper exists, broadcasting in a radio station will be a valid substitute: Provided, further, That mere posting shall be deemed sufficient if both newspapers and radio station are not available\nf. Fifteen (15) days after such publication, the Ancestral Domains Office shall investigate and inspect each application, and if found to be meritorious, shall cause a parcellary survey of the area being claimed. The Ancestral Domains office shall reject any claim that is deemed patently false or fraudulent after inspection and verification. In case of rejection, the Ancestral Domains office shall give the applicant due notice, copy furnished all concerned, containing the grounds for denial. The denial shall be appealable to the NCIP. In case of conflicting claims among individual or indigenous corporate claimants, the Ancestral domains Office shall cause the contending parties to meet and assist them in coming up with a preliminary resolution of the conflict, without prejudice to its full adjudication according to Sec. 62 of this Act. In all proceedings for the identification or delineation of the ancestral domains as herein provided, the Director of Lands shall represent the interest of the Republic of the Philippines; and\ng. The Ancestral Domains Office shall prepare and submit a report on each and every application surveyed and delineated to the NCIP, which shall, in turn, evaluate or corporate (family or clan) claimant over ancestral lands."}},{"id":"PH-H6846-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Fraudulent Claims. - The Ancestral Domains Office may, upon written request from the ICCs/IPs, review existing claims which have been fraudulently acquired by any person or community. Any claim found to be fraudulently acquired by, and issued to, any person or community may be cancelled by the NCIP after due notice and hearing of all parties concerned."}},{"id":"PH-H6846-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Communal Rights. - Subject to Section 56 hereof, areas within the ancestral domains, whether delineated or not, shall be presumed to be communally held: Provide, That communal rights under this Act shall not be construed as co-ownership as provided in Republic Act. No. 386, otherwise known as the New Civil Code."}},{"id":"PH-H6846-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Existing Property Rights Regimes. - Property rights within the ancestral domains already existing and/or vested upon effectivity of this Act, shall be recognized and respected."}},{"id":"PH-H6846-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Natural Resources within Ancestral Domains. - The ICCs/IPs shall have the priority rights in the harvesting, extraction, development or exploitation of any natural resources within the ancestral domains. A non-member of the ICCs/IPs concerned may be allowed to take part in the development and utilization of the natural resources for a period of not exceeding twenty-five (25) years renewable for not more than twenty-five (25) years: Provided, That a formal and written agreement is entered into with the ICCs/IPs concerned or that the community, pursuant to its own decision making process, has agreed to allow such operation: Provided, finally, That the all extractions shall be used to facilitate the development and improvement of the ancestral domains."}},{"id":"PH-H6846-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Environmental Consideration. - Ancestral domains or portion thereof, which are found necessary for critical watersheds, mangroves wildlife sanctuaries, wilderness, protected areas, forest cover, or reforestation as determined by the appropriate agencies with the full participation of the ICCs/IPs concerned shall be maintained, managed and developed for such purposes. The ICCs/IPs concerned shall be given the responsibility to maintain, develop, protect and conserve such areas with the full and effective assistance of the government agencies. Should the ICCs/IPs decide to transfer the responsibility over the areas, said decision must be made in writing. The consent of the ICCs/IPs should be arrived at in accordance with its customary laws without prejudice to the basic requirement of the existing laws on free and prior informed consent: Provided, That the transfer shall be temporary and will ultimately revert to the ICCs/IPs in accordance with a program for technology transfer: Provided, further, That no ICCs/IPs shall be displaced or relocated for the purpose enumerated under this section without the written consent of the specific persons authorized to give consent."}},{"id":"PH-H6846-A59","no":59,"noLabel":{"en":"Section 59."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Certification Precondition. - all department and other governmental agencies shall henceforth be strictly enjoined from issuing, renewing, or granting any concession, license or lease, or entering into any production-sharing agreement, without prior certification from the NCIP that the area affected does not overlap with any ancestral domain. Such certificate shall only be issued after a field-based investigation is conducted by the Ancestral Domain Office of the area concerned: Provided, That no certificate shall be issued by the NCIP without the free and prior informed and written consent of the ICCs/IPs concerned: Provided, further, That no department, government agency or government-owned or -controlled corporation may issue new concession, license, lease, or production sharing agreement while there is pending application CADT: Provided, finally, That the ICCs/IPs shall have the right to stop or suspend, in accordance with this Act, any project that has not satisfied the requirement of this consultation process."}},{"id":"PH-H6846-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Exemption from Taxes. - All lands certified to be ancestral domains shall be exempt from real property taxes, specially levies, and other forms of exaction except such portion of the ancestral domains as are actually used for large-scale agriculture, commercial forest plantation and residential purposes and upon titling by other by private person: Provided, that all exactions shall be used to facilitate the development and improvement of the ancestral domains."}},{"id":"PH-H6846-A61","no":61,"noLabel":{"en":"Section 61."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Temporary Requisition Powers. - Prior to the establishment of an institutional surveying capacity whereby it can effectively fulfill its mandate, but in no case beyond three (3) years after its creation, the NCIP is hereby authorized to request the Department of Environment and Natural Resources (DENR) survey teams as well as other equally capable private survey teams, through a Memorandum of Agreement (MOA), to delineate ancestral domain perimeters. The DENR Secretary shall accommodate any such request within one (1) month of its issuance: Provided, That the Memorandum of Agreement shall stipulate, among others, a provision for technology transfer to the NCIP."}},{"id":"PH-H6846-A62","no":62,"noLabel":{"en":"Section 62."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Resolution of Conflicts. - In cases of conflicting interest, where there are adverse claims within the ancestral domains as delineated in the survey plan, and which cannot be resolved, the NCIP shall hear and decide, after notice to the proper parties, the disputes arising from the delineation of such ancestral domains: Provided, That if the dispute is between and/or among ICCs/IPs regarding the traditional boundaries of their respective ancestral domains, customary process shall be followed. The NCIP shall promulgate the necessary rules and regulations to carry out its adjudicatory functions: Provided, further, That in any decision, order, award or ruling of the NCIP on any ancestral domain dispute or on any matter pertaining to the application, implementation, enforcement and interpretation of this Act may be brought for Petition for Review to the Court of Appeals within fifteen (15) days from receipt of a copy thereof."}},{"id":"PH-H6846-A63","no":63,"noLabel":{"en":"Section 63."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Applicable Laws. - Customary laws, traditions and practices of the ICCs/IPs of the land where the conflict arises shall be applied first with respect to property rights, claims and ownerships, hereditary succession and settlement of land disputes. Any doubt or ambiguity in the application of laws shall be resolved in favor of the ICCs/IPs."}},{"id":"PH-H6846-A64","no":64,"noLabel":{"en":"Section 64."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Remedial Measures. - Expropriation may be resorted to in the resolution of conflicts of interest following the principle of the \"common good\". The NCIP shall take appropriate legal action for the cancellation of officially documented titles which were acquired illegally: Provided, That such procedure shall ensure that the rights of possessors in good faith shall be respected: Provided, further, That the action for cancellation shall be initiated within two (2) years from the effectivity of this Act: Provided, finally, That the action for reconveyance shall be a period of ten (10) years in accordance with existing laws.\nJURISDICTION AND PROCEDURES FOR ENFORCEMENT OF RIGHTS"}},{"id":"PH-H6846-A65","no":65,"noLabel":{"en":"Section 65."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Primary of Customary Laws and Practices. - When disputes involve ICCs/IPs, customary laws and practices shall be used to resolve the dispute."}},{"id":"PH-H6846-A66","no":66,"noLabel":{"en":"Section 66."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Jurisdiction of the NCIP. - The NCIP, through its regional offices, shall have jurisdiction over all claims and disputes involving rights of ICCs/IPs; Provided, however, That no such dispute shall be brought to the NCIP unless the parties have exhausted all remedies provided under their customary laws. For this purpose, a certification shall be issued by the Council of Elders/Leaders who participated in the attempt to settle the dispute that the same has not been resolved, which certification shall be a condition precedent to the filing of a petition with the NCIP."}},{"id":"PH-H6846-A67","no":67,"noLabel":{"en":"Section 67."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Appeals to the Court of Appeals. - Decisions of the NCIP shall be appealable to the Court of Appeals by way of a petition for review."}},{"id":"PH-H6846-A68","no":68,"noLabel":{"en":"Section 68."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Execution of Decisions, Awards, Orders. - Upon expiration of the period here provided and no appeal is perfected by any of the contending parties, the Hearing Officer of the NCIP, on its own initiative or upon motion by the prevailing party, shall issue a writ of execution requiring the sheriff or the proper officer to execute final decisions, orders or awards of the Regional Hearing Officer of the NCIP."}},{"id":"PH-H6846-A69","no":69,"noLabel":{"en":"Section 69."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Quasi-Judicial Powers of the NCIP. - The NCIP shall have the power and authority:\na. To promulgate rules and regulations governing the hearing and disposition of cases filed before it as well as those pertaining to its internal functions and such rules and regulations as may be necessary to carry out the purposes of this Act;\nb. To administer oaths, summon the parties to a controversy, issue subpoenas requiring the attendance and testimony of witnesses or the production of such books, papers, contracts, records, agreements and other document of similar nature as may be material to a just determination of the matter under investigation or hearing conducted in pursuance of this Act;\nc. To hold any person in contempt, directly or indirectly, and impose appropriate penalties therefor; and\nd. To enjoin any or all acts involving or arising from any case pending therefore it which, if not restrained forthwith, may cause grave or irreparable damage to any of the parties to the case or seriously affect social or economic activity."}},{"id":"PH-H6846-A70","no":70,"noLabel":{"en":"Section 70."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"No restraining Order or Preliminary Injunction. - No inferior court of the Philippines shall have the jurisdiction to issue any restraining order or writ of preliminary injunction against the NCIP or any of its duly authorized or designated offices in any case, dispute or controversy to, or interpretation of this Act and other pertinent laws relating to ICCs/IPs and ancestral domains.\nANCESTRAL DOMAINS FUND"}},{"id":"PH-H6846-A71","no":71,"noLabel":{"en":"Section 71."},"chapter":{"en":"CHAPTER X"},"text":{"en":"Ancestral Domains Fund. - There is hereby created a special fund, to be known as the Ancestral Domains Fund, an initial amount of the One Hundred thirty million pesos(P130,000,000) to cover compensation for expropriated lands, delineation and development of ancestral domains. An amount of Fifty million pesos (P50,000,000) shall be sourced from the gross income of the Philippine Charity Sweepstakes Office (PCSO) from its lotto operation, Ten millions pesos (P10,000,000) from the gross receipts of the travel tax of the preceding year, the fund of the Social Reform Council intended for survey and delineation of ancestral lands/domains, and such other source as the government may be deem appropriate. Thereafter such amount shall be included in the annual General Appropriations Act. Foreign as well as local funds which are made available for the ICCs/IPs through the government of the Philippines shall be coursed through the NCIP. The NCIP may also solicit and receive donations, endowments shall be exempted from income or gift taxes and all other taxes, charges or fees imposed by the government or any political subdivision or instrumentality thereof.\nPENALTIES"}},{"id":"PH-H6846-A72","no":72,"noLabel":{"en":"Section 72."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Punishable Acts and Applicable Penalties. - Any person who commits violation of any of the provisions of this Act, such as, but not limited to, authorized and/or unlawful intrusion upon any ancestral lands or domains as stated in Sec. 10, Chapter III, or shall commit any of the prohibited acts mentioned in Sections 21 and 24, Chapter V, Section 33, Chapter VI hereof, shall be punished in accordance with the customary laws of the ICCs/IPs concerned: Provided, That no such penalty shall be cruel, degrading or inhuman punishment: Provided, further, That neither shall the death penalty or excessive fines be imposed. This provision shall be without prejudice to the right of any ICCs/IPs to avail of the protection of existing laws. In which case, any person who violates any provision of this Act shall, upon conviction, be punished by imprisonment of not less than nine (9) months but not more than twelve (12) years or a fine not less than One hundred thousand pesos (P100,000) nor more than Five hundred thousand pesos (P500,000) or both such fine and imprisonment upon the discretion of the court. In addition, he shall be obliged to pay to the ICCs/IPs concerned whatever damage may have been suffered by the latter as a consequence of the unlawful act."}},{"id":"PH-H6846-A73","no":73,"noLabel":{"en":"Section 73."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Persons Subject to Punishment. - If the offender is a juridical person, all officers such as, but not limited to, its president, manager, or head of office responsible for their unlawful act shall be criminally liable therefor, in addition to the cancellation of certificates of their registration and/or license: Provided, That if the offender is a public official, the penalty shall include perpetual disqualification to hold public office.\nMERGER OF THE OFFICE FOR NORTHERN CULTURAL COMMUNITIES (ONCC) AND THE OFFICE FOR SOUTHERN CULTURAL COMMUNITIES (OSCC)"}},{"id":"PH-H6846-A74","no":74,"noLabel":{"en":"Section 74."},"chapter":{"en":"CHAPTER XII"},"text":{"en":"Merger of ONCC/OSCC. - The Office for Northern Cultural Communities (ONCC) and the Office of Southern Cultural Communities (OSCC), created under Executive Order Nos. 122-B and 122-C respectively, are hereby merged as organic offices of the NCIP and shall continue to function under a revitalized and strengthened structures to achieve the objectives of the NCIP: Provided, That the positions of Regional Directors and below, are hereby phased-out upon the effectivity of this Act: Provided, further, That officials and employees of the phased-out offices who may be qualified may apply for reappointment with the NCIP and may be given prior rights in the filing up of the newly created positions of NCIP, subject to the qualifications set by the Placement Committee: Provided, furthermore, That in the case where an indigenous person and a non-indigenous person with similar qualifications apply for the same position, priority shall be given to the former. Officers and employees who are to be phased-out as a result of the merger of their offices shall be entitled to gratuity a rate equivalent to one and a half (1 1/2) months salary for every year of continuous and satisfactory service rendered or the equivalent nearest fraction thereof favorable to them on the basis of the highest salary received. If they are already entitled to retirement benefits or the gratuity herein provided. Officers and employees who may be reinstated shall refund such retirement benefits or gratuity received: Provided, finally That absorbed personnel must still meet the qualifications and standards set by the Civil Service and the Placement Committee herein created."}},{"id":"PH-H6846-A75","no":75,"noLabel":{"en":"Section 75."},"chapter":{"en":"CHAPTER XII"},"text":{"en":"Transition Period. - The ONCC/OSCC shall have a period of six (6) months from the effectivity of this Act within which to wind up its affairs and to conduct audit of its finances."}},{"id":"PH-H6846-A76","no":76,"noLabel":{"en":"Section 76."},"chapter":{"en":"CHAPTER XII"},"text":{"en":"Transfer of Assets/Properties. - All real and personal properties which are vested in, or belonging to, the merged offices as aforestated shall be transferred to the NCIP without further need of conveyance, transfer or assignment and shall be held for the same purpose as they were held by the former offices: Provided, That all contracts, records and documents shall be transferred to the NCIP. All agreements and contracts entered into by the merged offices shall remain in full force and effect unless otherwise terminated, modified or amended by the NCIP."}},{"id":"PH-H6846-A77","no":77,"noLabel":{"en":"Section 77."},"chapter":{"en":"CHAPTER XII"},"text":{"en":"Placement Committee. - Subject to rules on government reorganization, a Placement Committee shall be created by the NCIP, in coordination with the Civil Service Commission, which shall assist in the judicious selection and placement of personnel in order that the best qualified and most deserving persons shall be appointed in the reorganized agency. The placement Committee shall be composed of seven (7) commissioners and an ICCs/IPs representative from each of the first and second level employees association in the Offices for Northern and Southern Cultural Communities (ONCC/OSCC), nongovernment organizations (NGOs) who have served the community for at least five (5) years and peoples organizations (POs) with at least five (5) years of existence. They shall be guided by the criteria of retention and appointment to be prepared by the consultative body and by the pertinent provisions of the civil service law.\nFINAL PROVISIONS"}},{"id":"PH-H6846-A78","no":78,"noLabel":{"en":"Section 78."},"chapter":{"en":"CHAPTER XIII"},"text":{"en":"Special Provision. - The City of Baguio shall remain to be governed by its Chapter and all lands proclaimed as part of its townsite reservation shall remain as such until otherwise reclassified by appropriate legislation: Provided, That prior land rights and titles recognized and/or required through any judicial, administrative or other processes before the effectivity of this Act shall remain valid: Provided, further, That this provision shall not apply to any territory which becomes part of the City of Baguio after the effectivity of this Act."}},{"id":"PH-H6846-A79","no":79,"noLabel":{"en":"Section 79."},"chapter":{"en":"CHAPTER XIII"},"text":{"en":"Appropriations. - The amount necessary to finance the initial implementation of this Act shall be charged against the current year's appropriation of the ONCC and the OSCC. Thereafter, such sums as may be necessary for its continued implementation shall be included in the annual General Appropriations Act."}},{"id":"PH-H6846-A80","no":80,"noLabel":{"en":"Section 80."},"chapter":{"en":"CHAPTER XIII"},"text":{"en":"Implementing Rules and Regulations. - Within sixty (60) days immediately after appointment, the NCIP shall issue the necessary rules and regulations, in consultation with the Committees on National Cultural Communities of the House of Representatives and the Senate, for the effective implementation of this Act."}},{"id":"PH-H6846-A81","no":81,"noLabel":{"en":"Section 81."},"chapter":{"en":"CHAPTER XIII"},"text":{"en":"Saving Clause. - This Act will not in any manner adversely affect the rights and benefits of the ICCs/IPs under other conventions, recommendations, international treaties, national laws, awards, customs and agreements."}},{"id":"PH-H6846-A82","no":82,"noLabel":{"en":"Section 82."},"chapter":{"en":"CHAPTER XIII"},"text":{"en":"Separability Clause. - In case any provision of this Act or any portion thereof is declared unconstitutional by a competent court, other provisions shall not be affected thereby."}},{"id":"PH-H6846-A83","no":83,"noLabel":{"en":"Section 83."},"chapter":{"en":"CHAPTER XIII"},"text":{"en":"Repealing Clause. - Presidential Decree NO. 410, Executive Order Nos. 122-B and 122-C, and all other laws, decrees, orders, rules and regulations or parts thereof inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6846-A84","no":84,"noLabel":{"en":"Section 84."},"chapter":{"en":"CHAPTER XIII"},"text":{"en":"Effectivity. - This Act shall take effect fifteen days (15) days upon its publication in the Official Gazette or in any two (2) newspapers of general circulation."}}],"pack":"ph-p97"};
  FT["PH-H6847"] = {"id":"PH-H6847","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8372_1997.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Barotac Nuevo市","en":"An Act Converting the Don Jose S. Monfort Memorial Hospital in the Municipality of Barotac Nuevo, Province of Iloilo, Into A Tertiary Hospital, Functioning As An Extension of the Western Visayas Medical Center in Iloilo City To Be Known As the Don Jose S. Monfort Medical Center Extension Hospital, and Appropriating Funds Therefor","orig":"An Act Converting the Don Jose S. Monfort Memorial Hospital in the Municipality of Barotac Nuevo, Province of Iloilo, Into A Tertiary Hospital, Functioning As An Extension of the Western Visayas Medical Center in Iloilo City To Be Known As the Don Jose S. Monfort Medical Center Extension Hospital, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 8372","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-02","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8372_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6847-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Don Jose S. Monfort Memorial Hospital in the Municipality of Barotac Nuevo, Province of Iloilo, is hereby converted into a tertiary hospital which shall function as an extension hospital of the Western Visayas Medical Center."}},{"id":"PH-H6847-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The said extension hospital shall serve as curative, teaching, training and medical research component of the Western Visayas Medical Center."}},{"id":"PH-H6847-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The extension hospital shall be under the supervision of the Western Visayas Medical Center in accordance with its charter in coordination with the Department of Health."}},{"id":"PH-H6847-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6847-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97"};
  FT["PH-H6848"] = {"id":"PH-H6848","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8373_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立San Enrique市","en":"An Act Establishing A National Comprehensive High School in the Municipality of San Enrique, Province of Iloilo To Be Known As the San Enrique National Comprehensive High School, and Appropriating Funds Therefor","orig":"An Act Establishing A National Comprehensive High School in the Municipality of San Enrique, Province of Iloilo To Be Known As the San Enrique National Comprehensive High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8373","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-06","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8373_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6848-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports a comprehensive national high school in the Municipality of San Enrique, Province of Iloilo, to be known as the San Enrique National Comprehensive High School."}},{"id":"PH-H6848-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6848-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6848-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97"};
  FT["PH-H6849"] = {"id":"PH-H6849","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8374_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Claveria市","en":"An Act Establishing A National High School in the Municipality of Claveria, Province of Cagayan, To Be Known As the Claveria National High School, and Appropriating Funds Therefor","orig":"An Act Establishing A National High School in the Municipality of Claveria, Province of Cagayan, To Be Known As the Claveria National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8374","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-08-11","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8374_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6849-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Department of Education, Culture and Sports, hereinafter referred to as the DECS, shall establish a national high school in the Municipality of Claveria, Province of Cagayan, to be known as the Claveria National High School."}},{"id":"PH-H6849-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6849-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97"};
