  FT["PH-H6852"] = {"id":"PH-H6852","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8377_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Lakewood市","en":"An Act Establishing A National High School in Barangay Tubod, Municipality of Lakewood, Province of Zamboanga Del Sur, To Be Known As the Tubod National High School, and Appropriating Funds Therefor","orig":"An Act Establishing A National High School in Barangay Tubod, Municipality of Lakewood, Province of Zamboanga Del Sur, To Be Known As the Tubod National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8377","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-08-11","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8377_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6852-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports, a national high school in Barangay Tubod, Municipality of Lakewood, Province of Zamboanga del Sur, to be known as the Tubod National High School."}},{"id":"PH-H6852-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6852-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97"};
  FT["PH-H6853"] = {"id":"PH-H6853","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8378_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立San Pedro市","en":"An Act Establishing A National High School in Pacita Complex I, Municipality of San Pedro, Province of Laguna, To Be Known As the Pacita Complex National High School, and Appropriating Funds Therefor","orig":"An Act Establishing A National High School in Pacita Complex I, Municipality of San Pedro, Province of Laguna, To Be Known As the Pacita Complex National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8378","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-08-11","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8378_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6853-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a national high school in Pacita Complex I, Municipality of San Pedro, Province of Laguna, to be known as the Pacita Complex National High School."}},{"id":"PH-H6853-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to implement the provisions of this Act."}},{"id":"PH-H6853-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6853-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97"};
  FT["PH-H6854"] = {"id":"PH-H6854","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8379_1997.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"将莱特省奥莫克市 Don Felipe Larrazabal 描笼涯的奥莫克市中学改设为奥莫克市工艺与贸易学校并为其拨款的法案","en":"An Act Converting the Ormoc City High School in Barangay Don Felipe Larrazabal, Ormoc City, Province of Leyte, Into A School of Arts and Trade, To Be Known As the Ormoc City School of Arts and Trade, and Appropriating Funds Therefor","orig":"An Act Converting the Ormoc City High School in Barangay Don Felipe Larrazabal, Ormoc City, Province of Leyte, Into A School of Arts and Trade, To Be Known As the Ormoc City School of Arts and Trade, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["trade","administrative","education"],"docNumber":"Republic Act No. 8379","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-09-09","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8379_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6854-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Ormoc City High School in Barangay Don Felipe Larrazabal, Ormoc City, Province of Leyte, is hereby converted into a school of arts and trade, to be known as the Ormoc City School of Arts and Trade."}},{"id":"PH-H6854-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The school shall offer degree courses in industrial arts and industrial education. It shall also offer technical and vocational courses which shall be open to elementary school graduates: Provided, however, That the general secondary curriculum of the Ormoc City High School shall be maintained."}},{"id":"PH-H6854-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All assets, fixed and movable, personnel and records of the Ormoc City High School and its facilities are hereby transferred and absorbed by the Ormoc City School of Arts and Trade: Provided, however, That the personnel therein employed under existing laws prior to absorption by the Ormoc City School of Arts and Trade are not impaired: Provided, further, That all incumbents shall remain in the same status until otherwise provided for by the Department of Education, Culture and Sports."}},{"id":"PH-H6854-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Education, Culture and Sports shall take the necessary steps for the conversion and operation of the school and for the effective implementation of this Act."}},{"id":"PH-H6854-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Ormoc City High School. Thereafter, such sums as may be necessary for the operation and maintenance of the Ormoc City School of Arts and Trade shall be included in the annual General Appropriations Act."}},{"id":"PH-H6854-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"All laws, decrees, executive orders and other issuances, or parts thereof which are inconsistent with this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H6854-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Ormoc City High School in Barangay Don Felipe Larrazabal, Ormoc City, Province of Leyte, Into A School of Arts and Trade, To Be Known As the Ormoc City School of Arts and Trade, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6855"] = {"id":"PH-H6855","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8380_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将碧瑶市Irisan描笼涯Pines City国立中学的Quirino中学附属校改设为正式国立中学，名称为Irisan国立中学，并为此拨款的法案","en":"An Act Converting the Quirino High School Annex of the Pines City National High School Located in Barangay Irisan, Baguio City, Into A Regular National High School To Be Known As the Irisan National High School, and Appropriating Funds Therefor","orig":"An Act Converting the Quirino High School Annex of the Pines City National High School Located in Barangay Irisan, Baguio City, Into A Regular National High School To Be Known As the Irisan National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8380","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8380_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6855-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Quirino High School Annex of the Pines City National High School which is located at Barangay Irisan, Baguio City, is hereby converted into a regular national high school to be known as the Irisan National High School."}},{"id":"PH-H6855-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Pines City National High School - Quirino School Annex. Thereafter, such sums as may be necessary for the operation and maintenance of the Irisan National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H6855-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApprved,"}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Quirino High School Annex of the Pines City National High School Located in Barangay Irisan, Baguio City, Into A Regular National High School To Be Known As the Irisan National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6856"] = {"id":"PH-H6856","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8381_1997.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"设立Guinyangan市","en":"An Act Converting Dungawan Barangay High School in the Municipality of Guinyangan, Province of Quezon, Into A National High School To Be Known As the Dungawan National High School, and Appropriating Funds Therefor","orig":"An Act Converting Dungawan Barangay High School in the Municipality of Guinyangan, Province of Quezon, Into A National High School To Be Known As the Dungawan National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8381","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-13","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8381_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6856-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The present Dungawan Barangay High School in the Municipality of Guinyangan, Province of Quezon, is hereby converted into a national high school to be known as the Dungawan National High School."}},{"id":"PH-H6856-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The said national high school shall provide secondary education, training and instructions primarily to pupils residing in the adjacent barangays of Dungawan, Mabini, Sta. Teresita, San Lorenzo, Villa Hiwasayan Sta. Maria, all in Municipality of Guinyangan, and Pisipis in the Municipality of Lopez, Quezon, but it shall not refuse to admit qualified pupils residing elsewhere in the district."}},{"id":"PH-H6856-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6856-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All personnel, assets, liabilities, and records of the Dungawan Barangay High School are hereby transferred to and absorbed by the Dungawan National High School."}},{"id":"PH-H6856-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6856-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97"};
  FT["PH-H6857"] = {"id":"PH-H6857","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8382_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将山区省Barlig市镇Kadaclan描笼涯的Kadaclan国立中学附属校从同市镇东Bontoc国立农业与职业中学分离，改设为独立的Kadaclan国立中学，并为此拨款的法案","en":"An Act Separating the Kadaclan National High School Annex in Barangay Kadaclan, Municipality of Barlig, From the Eastern Bontoc National Agricultural and Vocational High School, Also Situated in the Municipality of Barlig, Mountain Province, and Converting the Same Into An Independent National High School To Be Known As the Kadaclan National High School, and Appropriating Funds Therefor","orig":"An Act Separating the Kadaclan National High School Annex in Barangay Kadaclan, Municipality of Barlig, From the Eastern Bontoc National Agricultural and Vocational High School, Also Situated in the Municipality of Barlig, Mountain Province, and Converting the Same Into An Independent National High School To Be Known As the Kadaclan National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education","environment"],"docNumber":"Republic Act No. 8382","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-13","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8382_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6857-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Kadaclan National High School Annex in Barangay Kadaclan, Municipality of Barlig, Mountain Province, is hereby separated from the Eastern Bontoc National Agricultural and Vocational High School, also in the Municipality of Barlig, Mountain Province, and converted into an independent national high school to be known as the Kadaclan National High School."}},{"id":"PH-H6857-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue orders, rules and circulars as may be necessary for the implementation of this Act."}},{"id":"PH-H6857-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Eastern Bontoc National Agricultural and Vocational High School. Thereafter, such sums as may be necessary for the operation and maintenance of the Kadaclan National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H6857-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Kadaclan National High School Annex in Barangay Kadaclan, Municipality of Barlig, From the Eastern Bontoc National Agricultural and Vocational High School, Also Situated in the Municipality of Barlig, Mountain Province, and Converting the Same Into An Independent National High School To Be Known As the Kadaclan National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6858"] = {"id":"PH-H6858","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8383_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将马拉邦市镇Tugatog描笼涯的Malabon市镇中学Tugatog附属校分离改设为Tugatog国立中学并为此拨款的法案","en":"An Act Separating the Malabon Municipal High School, Tugatog Annex, Situated in Barangay Tugatog, From the Malabon Municipal High School Situated in Barangay Hulong-duhat, All in the Municipality of Malabon, Metro Manila, and Converting the Same Into A Separate and Independent National High School To Be Known As the Tugatog National High School, and Appropriating Funds Therefor","orig":"An Act Separating the Malabon Municipal High School, Tugatog Annex, Situated in Barangay Tugatog, From the Malabon Municipal High School Situated in Barangay Hulong-duhat, All in the Municipality of Malabon, Metro Manila, and Converting the Same Into A Separate and Independent National High School To Be Known As the Tugatog National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8383","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8383_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6858-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Malabon Municipal High School, Tugatog Annex, situated in Barangay Tugatog, is hereby separated from the Malabon Municipal High School situated in Barangay Hulong-Duhat, all in the Municipality of Malabon, Metro Manila, and shall operate independently under the supervision of the Department of Education, Culture and Sports, to be known as the Tugatog National High School."}},{"id":"PH-H6858-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Malabon Municipal High School, Tugatog Annex. Thereafter, such sums as may be necessary for the operation and maintenance of the Tugatog National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H6858-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Malabon Municipal High School, Tugatog Annex, Situated in Barangay Tugatog, From the Malabon Municipal High School Situated in Barangay Hulong-duhat, All in the Municipality of Malabon, Metro Manila, and Converting the Same Into A Separate and Independent National High School To Be Known As the Tugatog National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6859"] = {"id":"PH-H6859","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8384_1997.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将阿帕约省 Calanasan 市镇阿帕约国立工业与农业中学（Eva Puzon 附属中学）从该校分离并改设为名为 Pio Da Lim 工艺与贸易学校的独立国立中学并拨款","en":"An Act Separating the Apayao National Industrial and Agricultural High School - (Eva Puzon Annex High School) in the Municipality of Calanasan, Province of Apayao, From the Apayao National Industrial and Agricultural High School in the Municipality of Calanasan, and Converting It Into A Separate and Independent National High School To Be Known As the Pio Da Lim Memorial School of Arts and Trades, and Appropriating Funds Therefor","orig":"An Act Separating the Apayao National Industrial and Agricultural High School - (Eva Puzon Annex High School) in the Municipality of Calanasan, Province of Apayao, From the Apayao National Industrial and Agricultural High School in the Municipality of Calanasan, and Converting It Into A Separate and Independent National High School To Be Known As the Pio Da Lim Memorial School of Arts and Trades, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education","environment","culture"],"docNumber":"Republic Act No. 8384","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-22","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8384_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6859-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Apayao National Industrial and Agricultural High School (Eva Puzon Annex High School) in the Municipality of Calanasan, Province of Apayao, is hereby separated from the Apayao National Industrial and Agricultural High School in the Municipality of Calanasan, and converted into a separate and independent school of arts and trades to be known as Pio Da Lim Memorial School of Arts and Trades."}},{"id":"PH-H6859-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The school shall offer secondary education proper, as well as vocational courses to carry out its objectives as may be authorized by the Secretary of the Department of Education, Culture and Sports in coordination with the Technical Education and Skills Development Authority (TESDA)."}},{"id":"PH-H6859-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Education, Culture and Sports shall issue rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H6859-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All personnel, assets, liabilities, and records of the Apayao National Industrial and Agricultural High School - (Eva Puzon Annex High School) are hereby transferred to and absorbed by the Pio Da Lim Memorial School of Arts and Trades."}},{"id":"PH-H6859-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Apayao National Industrial Agricultural High School - (Eva Puzon High School Annex). Thereafter, such sums as may be necessary for the operation and maintenance of Pio Da Lim Memorial School of Arts and Trades shall be included in the annual General Appropriations Act."}},{"id":"PH-H6859-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Apayao National Industrial and Agricultural High School - (Eva Puzon Annex High School) in the Municipality of Calanasan, Province of Apayao, From the Apayao National Industrial and Agricultural High School in the Municipality of Calanasan, and Converting It Into A Separate and Independent National High School To Be Known As the Pio Da Lim Memorial School of Arts and Trades, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6860"] = {"id":"PH-H6860","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8385_1997.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将西内格罗斯省圣卡洛斯市Euzkara的Don Carlos Ledesma国立中学分校分离，改设为独立的Julio Ledesma国立中学，并为此拨款的法案","en":"An Act Separating the Don Carlos Ledesma National High School-extension Located At Euzkara, San Carlos City, Negros Occidental, From the Don Carlos Ledesma National High School-main Located At Buluangan, San Carlos City, Negros Occidental, and Converting It Into A Separate and Independent National High School To Be Known As the Julio Ledesma National High School, and Appropriating Funds Therefor","orig":"An Act Separating the Don Carlos Ledesma National High School-extension Located At Euzkara, San Carlos City, Negros Occidental, From the Don Carlos Ledesma National High School-main Located At Buluangan, San Carlos City, Negros Occidental, and Converting It Into A Separate and Independent National High School To Be Known As the Julio Ledesma National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8385","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8385_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6860-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Don Carlos Ledesma National High School-Extension located at Euzkara, San Carlos City, Negros Occidental, is hereby separated from the Don Carlos Ledesma National High School-Main located at Buluangan, San Carlos City, Negros Occidental, and converted into a separate and independent national high school, to be known as the Julio Ledesma National High School."}},{"id":"PH-H6860-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports (DECS) shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H6860-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, assets, liabilities, and records of the Don Carlos Ledesma National High School - Extension are hereby transferred to and absorbed by the Julio Ledesma National High School."}},{"id":"PH-H6860-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriation of the Julio Ledesma National High School and thereafter in the annual General Appropriations Act."}},{"id":"PH-H6860-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Don Carlos Ledesma National High School-extension Located At Euzkara, San Carlos City, Negros Occidental, From the Don Carlos Ledesma National High School-main Located At Buluangan, San Carlos City, Negros Occidental, and Converting It Into A Separate and Independent National High School To Be Known As the Julio Ledesma National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6861"] = {"id":"PH-H6861","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8386_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将达沃市Marilog区Buda描笼涯的Marilog国立中学附属校从Marilog国立中学分离，改设为独立的Buda国立中学的法案","en":"An Act Separating the Marilog National High School Annex Located in Barangay Buda From the Marilog National High School, Both in Marilog District, Davao City, and Converting It Into A Separate and Independent National High School To Be Known As the Buda National High School","orig":"An Act Separating the Marilog National High School Annex Located in Barangay Buda From the Marilog National High School, Both in Marilog District, Davao City, and Converting It Into A Separate and Independent National High School To Be Known As the Buda National High School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8386","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8386_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6861-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Marilog National High School Annex located in Barangay Buda, Marilog District, Davao City, is hereby separated from the Marilog National High School, also of the same city and converted into a separate and independent national high school to be known as the Buda National High School."}},{"id":"PH-H6861-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H6861-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Marilog National High School - Barangay Buda Annex. Thereafter, such sums as may be necessary for the operation and maintenance of the Buda National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H6861-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Marilog National High School Annex Located in Barangay Buda From the Marilog National High School, Both in Marilog District, Davao City, and Converting It Into A Separate and Independent National High School To Be Known As the Buda National High School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6862"] = {"id":"PH-H6862","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8387_1997.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将高山省 Besao 市镇 Panabungen 国立中学附属校从 Tadian 工艺与贸易学校分离，改设为独立的 Panabungen 工艺与贸易学校并拨款","en":"An Act Separating the Panabungen National High School Annex in Barangay Panabungen, Municipality of Besao, Mountain Province, From the Tadian School of Arts and Trade in the Municipality of Tadian, Mountain Province, and Converting It Into An Independent School of Arts, Trade and Home Industries To Be Known As the Panabungen School of Arts, Trade and Home Industries, and Appropriating Funds Therefor","orig":"An Act Separating the Panabungen National High School Annex in Barangay Panabungen, Municipality of Besao, Mountain Province, From the Tadian School of Arts and Trade in the Municipality of Tadian, Mountain Province, and Converting It Into An Independent School of Arts, Trade and Home Industries To Be Known As the Panabungen School of Arts, Trade and Home Industries, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["trade","administrative","education"],"docNumber":"Republic Act No. 8387","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-22","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8387_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6862-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Panabungen National School Annex in Barangay Panabungen, Municipality of Besao, Mountain Province, is hereby separated from the Tadian School of Arts and Trade in the Municipality of Tadian, Mountain Province and converted into an independent school of arts, trade and home industries, to be known as the Panabungen School of Arts, Trade and Home Industries."}},{"id":"PH-H6862-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All assets fixed and movable, personnel and records of the Panabungen National High School Annex are hereby transferred to the Panabungen School of Arts, Trade and Home Industries: Provided, That the positions, rights and security of tenure of personnel therein employed under existing law pertaining to separation from the mother school are not impaired."}},{"id":"PH-H6862-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All parcels of land belonging to the government occupied by the Panabungen National High School Annex are hereby declared to be the property of the Panabungen School of Arts, Trade and Home Industries and shall be titled under that name: Provided, That should the Panabungen School of Arts, Trade and Home Industries cease to exist or is abolished or such parcels of land are no longer needed by the Panabungen School of Arts, Trade and Home Industries, the same shall revert to Mountain Province."}},{"id":"PH-H6862-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Tadian School of Arts and Trade - Panabungen National High School Annex. Thereafter, such sums as may be necessary for the operation and maintenance of Panabungen School of Arts, Trade and Home Industries shall be included in the annual General Appropriations Act."}},{"id":"PH-H6862-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such orders, rules and circulars as may be necessary for the implementation of this Act."}},{"id":"PH-H6862-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Panabungen National High School Annex in Barangay Panabungen, Municipality of Besao, Mountain Province, From the Tadian School of Arts and Trade in the Municipality of Tadian, Mountain Province, and Converting It Into An Independent School of Arts, Trade and Home Industries To Be Known As the Panabungen School of Arts, Trade and Home Industries, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6863"] = {"id":"PH-H6863","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8388_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将达沃市托里尔区巴亚巴斯路口描笼涯Piedad的Doña Carmen Denia国立中学附属校从该校分离，改设为独立的巴亚巴斯路口国立中学，并为此拨款的法案","en":"An Act Separating the Doña Carmen Denia National High School Annex At Piedad, Barangay Crossing Bayabas, Toril District, From the Doña Carmen Denia National High School, Toril Poblacion, Both in Davao City and Converting It Into A Separate and Independent National High School To Be Known As the Crossing Bayabas National High School","orig":"An Act Separating the Doña Carmen Denia National High School Annex At Piedad, Barangay Crossing Bayabas, Toril District, From the Doña Carmen Denia National High School, Toril Poblacion, Both in Davao City and Converting It Into A Separate and Independent National High School To Be Known As the Crossing Bayabas National High School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8388","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8388_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6863-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Doña Carmen Denia National High School Annex at Piedad, Barangay Crossing Bayabas, Toril District, Davao City, is hereby separated from the Doña Carmen Denia National High School, Toril Poblacion, both in Davao City and converted into a separate and independent national high school to be known as the Crossing Bayabas National High School."}},{"id":"PH-H6863-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H6863-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Doña Carmen Denia National High School – Barangay Crossing Bayabas Annex. Thereafter, such sums as may be necessary for the operation and maintenance of the Crossing Bayabas National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H6863-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Doña Carmen Denia National High School Annex At Piedad, Barangay Crossing Bayabas, Toril District, From the Doña Carmen Denia National High School, Toril Poblacion, Both in Davao City and Converting It Into A Separate and Independent National High School To Be Known As the Crossing Bayabas National High School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6864"] = {"id":"PH-H6864","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8389_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Pasay市","en":"An Act Creating the Kalayaan National High School in the City of Pasay, Metro Manila, Providing Funds Therefor","orig":"An Act Creating the Kalayaan National High School in the City of Pasay, Metro Manila, Providing Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8389","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8389_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6864-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be a Pasay City Kalayaan National High School to be located at Barangay 183 in the City of Pasay, Metro Manila, under the supervision of the Department of Education, Culture and Sports."}},{"id":"PH-H6864-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6864-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97"};
  FT["PH-H6865"] = {"id":"PH-H6865","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8390_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Batac市","en":"An Act Creating A National High School in Barangay San Pedro, Municipality of Batac, Province of Ilocos Norte, To Be Known As the Crispina Marcos-valdez National High School, and Appropriating Funds Therefor","orig":"An Act Creating A National High School in Barangay San Pedro, Municipality of Batac, Province of Ilocos Norte, To Be Known As the Crispina Marcos-valdez National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8390","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8390_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6865-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a national high school in Barangay San Pedro, Municipality of Batac, Province of Ilocos Norte, to be known as the Crispina Marcos-Valdez National High School."}},{"id":"PH-H6865-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6865-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6865-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97"};
  FT["PH-H6866"] = {"id":"PH-H6866","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8391_1997.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"在大马尼拉 Valenzuela 市将 Canumay 附属校从该市市镇中学分离，设立 Canumay 国立中学并为其提供经费","en":"An Act Creating the Canumay National High School in Valenzuela, Metro Manila, By Separating the Canumay Annex From the Valenzuela Municipal High School, and Providing Funds Therefor","orig":"An Act Creating the Canumay National High School in Valenzuela, Metro Manila, By Separating the Canumay Annex From the Valenzuela Municipal High School, and Providing Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8391","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8391_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6866-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Canumay Annex of Valenzuela Municipal High School located in Barangay Canumay, Municipality of Valenzuela, Metro Manila, is hereby separated from the said Valenzuela Municipal High School and thereafter created as an independent educational institution, to be known as the Canumay National High School."}},{"id":"PH-H6866-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All properties and assets presently pertaining or belonging to the Valenzuela Municipal High School – Canumay Annex are hereby transferred to the newly created Canumay National High School."}},{"id":"PH-H6866-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Valenzuela Municipal High School - Canumay Annex. Thereafter, such sums as may be necessary for the operations and maintenance of the Canumay National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H6866-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall make the necessary directive to effect the separation of Canumay Annex from the Valenzuela Municipal High School, as well as to bring about the smooth operation of the Canumay National High School under this Act."}},{"id":"PH-H6866-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p97","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Canumay National High School in Valenzuela, Metro Manila, By Separating the Canumay Annex From the Valenzuela Municipal High School, and Providing Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6867"] = {"id":"PH-H6867","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8392_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Malvar市","en":"An Act Establishing A Vocational High School in the Municipality of Malvar, Province of Batangas, To Be Known As Don Julio Leviste Memorial Vocational High School, and Appropriating Funds Therefor","orig":"An Act Establishing A Vocational High School in the Municipality of Malvar, Province of Batangas, To Be Known As Don Julio Leviste Memorial Vocational High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8392","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8392_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6867-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a vocational high school in the Municipality of Malvar, Province of Batangas, to be known as the Don Julio Leviste Memorial Vocational High School."}},{"id":"PH-H6867-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue the necessary rules and regulations to implement the provisions of this Act."}},{"id":"PH-H6867-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}}],"pack":"ph-p97"};
